/* Presentation only: preserve the dashboard's existing controls and state. */
.ss-portal {
  --ss-premium-ink:#142238;
  --ss-premium-muted:#5b6470;
  --ss-premium-gold:#ddc18c;
  --ss-premium-card:#fff;
  --ss-premium-card-strong:#fff;
  --ss-premium-shadow:0 8px 24px rgba(20,34,56,.05);
  --ss-premium-shadow-strong:0 12px 30px rgba(20,34,56,.09);
  background:#faf9f5;
  color:#142238;
}
.ss-portal .ss-bg {background:#faf9f5!important;}
.ss-portal .ss-bg::before,.ss-portal .ss-bg::after,.ss-portal .ss-store-card::before {display:none!important;}
.ss-portal .ss-h1 {color:#142238!important;font-weight:800!important;line-height:1.04!important;letter-spacing:-.055em!important;}
.ss-portal .ss-sub {color:#5b6470!important;line-height:1.6!important;}
.ss-portal :is(.ss-card,.ss-store-card,.ss-user-pill) {background:#fff!important;border:1px solid #e2dfd5!important;box-shadow:0 8px 24px rgba(20,34,56,.05)!important;backdrop-filter:none!important;}
.ss-portal :is(.ss-card,.ss-store-card) {border-radius:18px!important;}
.ss-portal .ss-logo-frame {background:#faf9f5!important;border:1px solid #e2dfd5!important;border-radius:14px!important;box-shadow:none!important;}
.ss-portal .ss-card-title {color:#142238!important;letter-spacing:-.025em!important;font-weight:750!important;}
.ss-portal .ss-card-subtitle {background:#f7f2e7!important;border-color:#e9dfc9!important;color:#715926!important;}
.ss-portal :is(.ss-btn-primary,.ss-open-btn,.ss-btn-seller) {background:#142238!important;color:#fff!important;border:1px solid #142238!important;border-radius:10px!important;box-shadow:none!important;font-weight:750!important;}
.ss-portal :is(.ss-btn-secondary,.ss-admin-btn,.ss-pill-btn) {background:#fff!important;color:#142238!important;border:1px solid #d9d8d0!important;border-radius:10px!important;box-shadow:none!important;font-weight:700!important;}
.ss-portal .ss-admin-btn {background:#eddec2!important;border-color:#ddc18c!important;}
.ss-portal :is(.ss-open-btn,.ss-admin-btn).ss-disabled {background:#eeede8!important;color:#73767c!important;border-color:#e2dfd5!important;}
.ss-portal .ss-btn-cta::after {display:none;}
.ss-portal :is(a,button,input):focus-visible {outline:3px solid #947337!important;outline-offset:3px;}
.ss-portal .ss-store-card.ss-clickrow:hover {box-shadow:0 12px 30px rgba(20,34,56,.09)!important;border-color:#c8b68f!important;}
@media(max-width:900px) {
  .ss-portal .ss-header {gap:16px;}
  .ss-portal .ss-store-card {padding:16px!important;grid-template-columns:72px minmax(0,1fr)!important;gap:12px!important;}
  .ss-portal .ss-logo-frame {width:72px!important;height:72px!important;}
  .ss-portal .ss-card-title {white-space:normal!important;overflow-wrap:anywhere;font-size:17px!important;line-height:1.25!important;}
  .ss-portal .ss-col-controls {grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:8px!important;}
  .ss-portal .ss-col-controls>:only-child {grid-column:1/-1;}
  .ss-portal .ss-col-controls .ss-leave-btn {grid-column:1/-1;min-height:40px!important;}
  .ss-portal .ss-col-controls :is(.ss-admin-btn,.ss-open-btn) {min-height:46px!important;}
  .ss-portal .ss-h1 {font-size:clamp(34px,9vw,44px)!important;}
}
@media(prefers-reduced-motion:reduce) {.ss-portal .ss-store-card {transform:none!important;}}

/* Keep real garment imagery, colors, prices and sizes; tidy phone spacing. */
/* Access notices must remain legible under every custom store palette. */
#MainContent .ps-hero--auth .ps-auth-card {background:#fff!important;color:#142238!important;border-radius:20px;}
#MainContent .ps-hero--auth .ps-auth-card .ps-title {color:#142238!important;}
#MainContent .ps-hero--auth .ps-auth-card .ps-sub {color:#5b6470!important;}
#MainContent .ps-hero--auth .ps-actions {display:flex;justify-content:center;flex-wrap:wrap;gap:10px;margin-top:20px;}
#MainContent .ps-hero--auth .ps-actions .ps-btn {display:inline-flex;align-items:center;justify-content:center;min-height:46px;padding:12px 18px;border:1px solid #d9d8d0;border-radius:10px;text-decoration:none;font-weight:700;}
#MainContent .ps-hero--auth .ps-actions .ps-btn-solid {background:#142238!important;color:#fff!important;}
#MainContent .ps-hero--auth .ps-actions .ps-btn-ghost {background:#faf9f5!important;color:#142238!important;}
@media(max-width:767px) {
  #MainContent:has(#ss-private-store-state) .product-grid__item {min-width:0!important;}
  #MainContent:has(#ss-private-store-state) .product-grid__item .ss-card-shell {border-radius:16px!important;border:1px solid #e2e2df!important;box-shadow:0 3px 12px rgba(20,34,56,.04)!important;}
  #MainContent:has(#ss-private-store-state) .product-grid__item .ss-card-shell .ss-image-stage {padding:8px!important;}
  #MainContent:has(#ss-private-store-state) .product-grid__item .ss-card-shell .ss-info-deck {padding:12px!important;gap:8px;justify-content:flex-start;}
  #MainContent:has(#ss-private-store-state) .product-grid__item .ss-card-shell .ss-title {margin:0!important;font-size:14px!important;line-height:1.35!important;font-weight:650!important;letter-spacing:-.015em!important;overflow-wrap:anywhere;}
  #MainContent:has(#ss-private-store-state) .product-grid__item .ss-card-shell .ss-swatch-row {margin:0!important;gap:6px;min-height:16px;flex-wrap:wrap;}
  #MainContent:has(#ss-private-store-state) .product-grid__item .ss-card-shell .ss-swatch {width:15px;height:15px;}
  #MainContent:has(#ss-private-store-state) .product-grid__item .ss-card-shell .ss-meta-row {margin-top:auto;padding-top:3px;gap:6px;flex-wrap:wrap;align-items:baseline;}
  #MainContent:has(#ss-private-store-state) .product-grid__item .ss-card-shell .ss-price {font-size:18px!important;font-weight:750!important;line-height:1.2;}
  #MainContent:has(#ss-private-store-state) .product-grid__item .ss-card-shell .ss-sizes {font-size:11px!important;line-height:1.3;}
  #MainContent:has(#ss-private-store-state) .product-grid__item .ss-card-shell .ss-includes-badge {max-width:calc(100% - 16px);font-size:9px!important;line-height:1.3;white-space:normal;}
}

{%- comment -%}
  STELLA & SAGE — PREMIUM CATALOG SYNC
  ✅ Logic: Unchanged (Safe AI Wiring Intact)
  ✅ Visuals: Upgraded to "SaaS Studio" aesthetic
  ✅ Mobile: Optimized for touch feedback & responsive sizing
{%- endcomment -%}

{%- liquid
  assign p = product_card_product | default: product
  assign lock_code = p.metafields.custom.logo_position | default: ''

  # --- LOGO SOURCE (DYNAMIC + PIXELCUT CLEAN URL) ---
  assign store_handle = ''
  if collection and collection.handle != blank
    assign store_handle = collection.handle
  endif
  if store_handle == blank
    assign store_handle = request.params.shop | default: '' | strip
  endif

  assign logo_url = ''
  if store_handle != blank
    assign _shop_meta = shop.metaobjects.custom_shop[store_handle]
    if _shop_meta
      assign _clean = _shop_meta.logo_clean_url.value | default: _shop_meta.logo_clean_url
      if _clean != blank
        assign logo_url = _clean
      else
        assign _logo = _shop_meta.logo.value | default: _shop_meta.logo
        if _logo != blank
          assign logo_url = _logo | image_url: width: 400
        endif
      endif
    endif
  endif

  # --- MASTER BOX SETTINGS ---
  assign pixel_ratio = p.featured_media.aspect_ratio | default: 1.0
  assign media_width = p.featured_media.width | default: 600
  assign media_height = p.featured_media.height | default: 600

  # --- SECOND IMAGE ---
  assign second_media = p.media[1]

  # --- ZONE READER ---
  # --- WHAT THIS LISTING INCLUDES ---
  #
  # This card is rendered with a `children` capture that the theme fills with
  # product-card-badges (and quick-add). It has never output `children`, so
  # every badge the theme produced — sale, sold out, and now the pro-builder
  # inclusion — was assembled and thrown away. Rendering `children` wholesale
  # would drop quick-add markup into a hand-built layout that has no place for
  # it, so the one badge that has to reach shoppers is drawn here directly,
  # from the same shared rule the theme card uses.
  assign zone_style = "top: 20%; left: 20%; width: 60%; height: 60%;"
  for tag in p.tags
    assign tag_down = tag | downcase
    if tag_down contains 'zone:'
      assign zone_parts = tag_down | remove: 'zone:' | split: '-'
      if zone_parts.size == 4
        capture zone_style
          echo "top:" | append: zone_parts[0] | append: "%; "
          echo "left:" | append: zone_parts[1] | append: "%; "
          echo "width:" | append: zone_parts[2] | append: "%; "
          echo "height:" | append: zone_parts[3] | append: "%;"
        endcapture
        break
      endif
    endif
  endfor
-%}

<div class="product-card ss-card-shell{% if second_media != nil %} ss-has-alt{% endif %}" data-product-id="{{ p.id }}">
  <a href="{{ p.url }}" class="ss-link-wrapper">

    {%- comment -%} IMAGE AREA {%- endcomment -%}
    <div class="ss-image-stage">
      {%- capture pro_extra -%}{%- render 'pro-listing-includes', product: p -%}{%- endcapture -%}
      {%- assign pro_extra = pro_extra | strip -%}
      {%- if pro_extra != blank -%}
        <span class="ss-includes-badge">{{ pro_extra }}</span>
      {%- endif -%}
      <div class="ss-master-box" style="aspect-ratio: {{ pixel_ratio }};">
        <div class="ss-image-layers">
          {%- if p.featured_media -%}
            <img src="{{ p.featured_media | image_url: width: 600 }}"
                 class="ss-shirt-img ss-img-primary"
                 loading="lazy"
                 width="{{ media_width }}"
                 height="{{ media_height }}"
                 alt="{{ p.featured_media.alt | escape }}">

            {%- if second_media != nil -%}
              <img src="{{ second_media | image_url: width: 600 }}"
                   class="ss-shirt-img ss-img-secondary"
                   loading="lazy"
                   width="{{ second_media.width | default: media_width }}"
                   height="{{ second_media.height | default: media_height }}"
                   alt="">
            {%- endif -%}

            {%- comment -%} OVERLAY LOGIC {%- endcomment -%}
            {%- if lock_code != blank and lock_code != 'approved' and lock_code != 'DELETED' -%}
              <div class="ss-zone-box" style="{{ zone_style }}">
                <div class="ss-logo-wrapper" style="{{ lock_code | replace: '|', ';' }}">
                  {%- if logo_url != blank -%}
                    <img src="{{ logo_url }}" class="ss-logo-img" width="200" height="200" alt="Logo">
                  {%- endif -%}
                </div>
              </div>
            {%- endif -%}

          {%- else -%}
            {{ 'product-1' | placeholder_svg_tag: 'ss-shirt-img ss-img-primary' }}
          {%- endif -%}
        </div>
      </div>
    </div>

    {%- comment -%} INFO AREA {%- endcomment -%}
    <div class="ss-info-deck">
      {%- comment -%}
        The badge on the image already says "Front & Back" / "Name & Number",
        so the title drops the matching suffix here. It keeps it everywhere a
        badge cannot reach — cart, order emails, search.
      {%- endcomment -%}
      {%- capture ss_card_title -%}
        {%- render 'pro-listing-title', product: p, badge: pro_extra -%}
      {%- endcapture -%}
      <h3 class="ss-title">{{ ss_card_title | strip }}</h3>

      {%- render 'ss-product-card-swatches', product: p -%}

      {%- comment -%}
        ss-card-sizes

        What sizes it comes in, opposite the price.

        The deck is title, swatches, price — and on a product with one colour
        the swatch row is absent, so the card ends in a band of empty white
        with a small price floating in it. That space is worth something: the
        question a parent outfitting a kid asks second, right after the price,
        is whether it comes in their size. Answering it on the card saves
        opening every product to find out which ones run youth.

        Read off the product's own Size option, so it is the real range and
        never a guess. Shopify keeps option values in the order they were
        created and our builders write them smallest-first, which is why the
        ends of that list are the ends of the range — sorting them would give
        "3XL - XS", since size names do not sort alphabetically.

        Nothing is shown for a product with one size or no size option: "S - S"
        is noise, and a card that says nothing is better than a card that says
        something empty.
      {%- endcomment -%}
      {%- assign ss_size_range = '' -%}
      {%- for opt in p.options_with_values -%}
        {%- assign opt_name = opt.name | downcase | strip -%}
        {%- if opt_name == 'size' and opt.values.size > 1 -%}
          {%- assign _first = opt.values | first -%}
          {%- assign _last = opt.values | last -%}
          {%- assign _first = _first.name | default: _first | strip -%}
          {%- assign _last = _last.name | default: _last | strip -%}
          {%- if _first != blank and _last != blank and _first != _last -%}
            {%- capture ss_size_range -%}{{ _first }}&ndash;{{ _last }}{%- endcapture -%}
          {%- endif -%}
          {%- break -%}
        {%- endif -%}
      {%- endfor -%}

      <div class="ss-meta-row">
        <span class="ss-price">{{ p.price | money_without_trailing_zeros }}</span>
        {%- if ss_size_range != blank -%}
          <span class="ss-sizes">{{ ss_size_range }}</span>
        {%- endif -%}
      </div>
    </div>
  </a>
</div>

<style>
  /* --- THE CONTAINER (The "Physical" Card) --- */
  .ss-card-shell {
    display: flex !important;
    flex-direction: column !important;
    background: #ffffff;
    border-radius: 12px;
    overflow: hidden;
    border: 1px solid rgba(0,0,0,0.06);
    height: 100%;
    position: relative;
  }

  /* WHY translateZ(0) IS GONE
     It was here as a "hardware acceleration" hint, which browsers have not
     needed for years. What it still does is force the card onto its own
     compositor layer, and on that layer `overflow: hidden` is applied by the
     compositor rather than during layout — which on iOS Safari is a known way
     for the bottom of a clipped box to stop being painted while everything
     above it renders normally. That is the reported symptom exactly: images
     and title fine, the price row at the bottom missing, phone only.

     Said plainly: this is a hypothesis, not a diagnosis. The card was rendered
     at 390px with the theme's real stylesheet and grid, in both grid views,
     and the price measured visible and inside the box every time — see
     tests/js_harness/product_card_mobile_harness.js. Headless Chromium on
     Linux is not iOS Safari, and this compositor behaviour is one of the
     things it does not reproduce.

     Removing it costs nothing: no animation here depends on it, and the hover
     transitions are desktop-only. If the price is still missing on a phone
     after this, the cause is elsewhere and the harness is where to add the
     case that catches it. */

  /* --- DESKTOP INTERACTION (Mouse Only) --- */
  @media (hover: hover) {
    /* Image swap: only when a second image exists */
    .ss-card-shell.ss-has-alt:hover .ss-img-primary {
      opacity: 0;
    }
    .ss-card-shell.ss-has-alt:hover .ss-img-secondary {
      opacity: 1;
    }
  }

  /* --- MOBILE INTERACTION (Touch Feedback) --- */
  .ss-card-shell:active {
    /* Slight "press down" effect when tapped on phone */
    transform: scale(0.98);
    border-color: rgba(0,0,0,0.15);
  }

  /* --- THE IMAGE STAGE --- */
  .ss-image-stage {
    width: 100%;
    position: relative;
    background-color: #f8f9fa;
    padding: 20px; /* Desktop Padding */
    box-sizing: border-box;
  }

  /* Reads as information about the product, not as a discount: a shopper who
     mistakes an inclusion for a promotion is worse off than one who missed it.
     Sits above .ss-zone-box (z-index 10) and .ss-logo-wrapper (11) so the
     admin logo overlay cannot cover it. */
  /* ONE RULE FOR THE WHOLE CARD: black lettering, on white.

     This pill has now been dark-on-white and white-on-dark, and each time the
     argument was about which background it happens to land on. It does not
     need to be an argument. The pill is opaque white and the letters are the
     same black as the price, so it reads the same on the stage's near-white
     padding and on a black hoodie that reaches the corner — there is no case
     left where it depends on the mockup.

     Pure white on a #f8f9fa stage has no edge of its own, so the ring and the
     shadow are what make it read as a chip rather than as loose text. They
     are load-bearing here, not decoration.

     Colour and opacity are pinned for the same reason as the price below. */
  .ss-includes-badge {
    position: absolute;
    top: 8px;
    left: 8px;
    z-index: 12;
    display: inline-block;
    padding: 5px 10px;
    border-radius: 999px;
    background: #ffffff !important;
    border: 1px solid rgba(17, 16, 14, 0.20);
    box-shadow: 0 1px 5px rgba(17, 16, 14, 0.20);
    color: #111111 !important;
    opacity: 1 !important;
    font-size: 11px;
    font-weight: 700;
    line-height: 1.2;
    letter-spacing: 0.02em;
    pointer-events: none;
  }

  /* --- COLOUR SWATCHES --- */
  .ss-swatch-row {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 5px;
    margin-top: 8px;
  }

  .ss-swatch {
    width: 14px;
    height: 14px;
    border-radius: 50%;
    /* Inset rather than an outline so a white or cream blank still reads as a
       circle against the card, without a ring heavy enough to distort the
       colour it is meant to be showing. */
    box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.18);
    flex: 0 0 auto;
  }

  .ss-swatch-more {
    font-size: 11px;
    font-weight: 600;
    color: rgba(0, 0, 0, 0.5);
    line-height: 1;
  }

  .ss-link-wrapper {
    text-decoration: none;
    color: inherit;
    display: flex;
    flex-direction: column;
    height: 100%;
  }

  .ss-master-box {
    position: relative;
    width: 100%;
    height: auto;
    display: block;
    mix-blend-mode: multiply;
  }

  /* --- IMAGE LAYERS WRAPPER --- */
  .ss-image-layers {
    position: absolute;
    top: 0; left: 0;
    width: 100%; height: 100%;
  }

  /* --- IMAGES & LAYERS --- */
  .ss-shirt-img {
    position: absolute;
    top: 0; left: 0;
    width: 100%; height: 100%;
    object-fit: contain;
    display: block;
    z-index: 1;
    transition: opacity 0.4s ease-in-out;
  }

  /* Primary always visible by default; secondary hidden */
  .ss-img-primary {
    opacity: 1;
  }
  .ss-img-secondary {
    opacity: 0;
  }

  .ss-zone-box { position: absolute; pointer-events: none; z-index: 10; overflow: hidden; }
  .ss-logo-wrapper { position: absolute; z-index: 11; }
  .ss-logo-img { width: 100%; height: auto; display: block; }

  /* --- TYPOGRAPHY --- */
  .ss-info-deck {
    padding: 16px 20px 20px 20px;
    text-align: left;
    background: #fff;
    flex-grow: 1;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
  }

  .ss-title {
    font-weight: 600;
    font-size: 15px;
    margin: 0 0 8px 0;
    color: #111111 !important;
    line-height: 1.4;
    letter-spacing: -0.01em;
  }

  /* The price is what a shopper is actually looking for, and it was the
     faintest thing on the card: 14px, weight 500, mid-grey. Against a white
     deck on a phone held at arm's length that reads as almost not there.
     It is now the strongest line in the deck after the title. */
  /* WHY THE COLOUR AND OPACITY ARE PINNED

     Blunt on purpose. These are the price and the size range: what a shopper
     reads to decide what something costs and whether it comes in their size.
     Losing them to a stylesheet nobody has found is worse than the cost of a
     specificity war nobody else is fighting.

     The stylesheet has since been found, and !important here was not what
     beat it. storefront-fixed-layouts.css repaints every span inside a
     product tile for the spray and pro designs — near-white, because on
     those designs the THEME's card goes dark inside. Ours does not: it keeps
     this white deck, so it took the near-white ink and nothing else. That is
     why one store read black and every other read white. The difference was
     never the store; it was which design its organiser had picked.

     That rule is !important too, at an id plus :has() no bare class can
     outrank, so it is answered where it can be — at the end of that same
     stylesheet, which hands this card its palette back under all six designs.
     These stay pinned regardless: they are what the restore is written to
     agree with, and they still stop anything that arrives without an id. */
  .ss-price {
    font-size: 16px;
    color: #111111 !important;
    opacity: 1 !important;
    font-weight: 700;
    letter-spacing: -0.01em;
  }

  /* --- WHAT SIZES IT COMES IN --- */
  .ss-meta-row {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 10px;
  }

  .ss-sizes {
    font-size: 12px;
    font-weight: 600;
    color: #111111 !important;
    opacity: 1 !important;
    white-space: nowrap;
  }

  /* --- MOBILE SPECIFIC OVERRIDES (Screens smaller than 768px) --- */
  @media screen and (max-width: 767px) {
    .ss-image-stage {
      padding: 10px; /* Tighten padding so image is bigger on phone */
    }
    .ss-info-deck {
      padding: 12px 14px; /* Less whitespace for text area */
    }
    .ss-title {
      font-size: 14px; /* Slightly smaller text prevents wrapping */
    }
    .ss-card-shell {
      border-radius: 8px; /* Slightly tighter corners on small screens */
    }
    /* Said again for phones rather than left to inherit. The price reading as
       near-invisible on mobile is what prompted this, and whatever washed it
       out, an explicit rule at the breakpoint cannot be washed out quietly. */
    .ss-price {
      font-size: 16px;
      color: #111111;
      font-weight: 700;
    }
    .ss-sizes {
      font-size: 11px;
    }
  }
</style>

{%- comment -%}One row, using saved Printful colors when present; starter builds fall back to their real Color option.{%- endcomment -%}
{%- assign saved_colors = product.metafields.custom.color_swatches.value -%}
{%- assign color_option = nil -%}
{%- for option in product.options_with_values -%}
  {%- assign option_name = option.name | downcase | strip -%}
  {%- if option_name == 'color' or option_name == 'colour' -%}
    {%- assign color_option = option -%}
    {%- break -%}
  {%- endif -%}
{%- endfor -%}
{%- assign color_count = color_option.values.size | default: 0 -%}
{%- if color_count > 0 -%}
  <div class="ss-swatch-row" aria-label="Available colors">
    {%- for value in color_option.values limit: 6 -%}
      {%- assign color_name = value.name | default: value -%}
      {%- assign normalized_name = color_name | downcase | strip -%}
      {%- assign color_hex = '' -%}
      {%- for saved in saved_colors -%}
        {%- assign saved_name = saved.name | downcase | strip -%}
        {%- if saved_name == normalized_name and saved.hex != blank -%}
          {%- assign color_hex = saved.hex -%}
          {%- break -%}
        {%- endif -%}
      {%- endfor -%}
      {%- if color_hex == blank and value.swatch.color -%}
        {%- assign color_hex = value.swatch.color -%}
      {%- endif -%}
      {%- if color_hex == blank -%}
        {%- capture color_hex -%}{%- render 'ss-fallback-color', name: normalized_name -%}{%- endcapture -%}
        {%- assign color_hex = color_hex | strip -%}
      {%- endif -%}
      {%- if color_hex != blank -%}
        <span class="ss-swatch" style="background: {{ color_hex | escape }};" title="{{ color_name | escape }}" role="img" aria-label="{{ color_name | escape }}"></span>
      {%- else -%}
        {%- comment -%}Unknown specialty colors stay named rather than displaying a misleading color.{%- endcomment -%}
        <span class="ss-swatch-more" title="{{ color_name | escape }}">{{ color_name | escape }}</span>
      {%- endif -%}
    {%- endfor -%}
    {%- if color_count > 6 -%}<span class="ss-swatch-more">+{{ color_count | minus: 6 }}</span>{%- endif -%}
  </div>
{%- endif -%}

{%- comment -%}
  Admin Powers safety guard + visual polish.
  The guard refuses to leave the admin page usable if Shopify serves a render
  for a different store than the ?shop= value in the address bar.
{%- endcomment -%}
<script>
  (function () {
    var expected = '';
    try { expected = new URLSearchParams(window.location.search).get('shop') || ''; }
    catch (e) { return; }
    expected = expected.trim().toLowerCase();
    if (!expected) return;

    var served = String((window.SSAP && window.SSAP.shopHandle) || '').trim().toLowerCase();
    if (!served || served === expected) return;

    var FLAG = 'ss_admin_shop_retry';
    var already = '';
    try { already = sessionStorage.getItem(FLAG) || ''; } catch (e) {}

    if (already !== expected) {
      try { sessionStorage.setItem(FLAG, expected); } catch (e) {}
      var url = new URL(window.location.href);
      url.searchParams.set('_ssr', Date.now().toString(36));
      window.location.replace(url.toString());
      return;
    }

    try { sessionStorage.removeItem(FLAG); } catch (e) {}
    var wrap = document.querySelector('.ap-wrap');
    if (wrap) wrap.setAttribute('hidden', 'hidden');

    var notice = document.createElement('div');
    notice.setAttribute('role', 'alert');
    notice.style.cssText =
      'max-width:640px;margin:64px auto;padding:26px 28px;border-radius:18px;' +
      'border:1px solid rgba(180,35,24,.28);background:#fff6f5;color:#3d1512;' +
      'font:500 15px/1.55 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;';
    notice.innerHTML =
      '<div style="font-weight:800;font-size:18px;margin-bottom:8px;">This page loaded the wrong store</div>' +
      '<p style="margin:0 0 14px;">You asked for <strong>' + expected.replace(/[<>&]/g, '') +
      '</strong> but the page came back for <strong>' + served.replace(/[<>&]/g, '') +
      '</strong>, so it has been stopped.</p>' +
      '<p style="margin:0 0 18px;">Open it again from your dashboard. If this keeps happening, tell us which store.</p>' +
      '<a href="/pages/portal" style="display:inline-block;padding:11px 18px;border-radius:999px;' +
      'background:#11100e;color:#fff;text-decoration:none;font-weight:700;">← Back to dashboard</a>';
    (document.body || document.documentElement).appendChild(notice);
  })();
</script>

<script>
  (function () {
    var mq = window.matchMedia('(max-width: 700px)');

    function rememberAndSet(el, mobileText) {
      if (!el) return;
      if (!el.dataset.ssDesktopLabel) el.dataset.ssDesktopLabel = (el.textContent || '').trim();
      if (!el.getAttribute('aria-label')) el.setAttribute('aria-label', el.dataset.ssDesktopLabel || mobileText);
      var wanted = mq.matches ? mobileText : el.dataset.ssDesktopLabel;
      if ((el.textContent || '').trim() !== wanted) el.textContent = wanted;
    }

    function syncMobileHero() {
      var actions = document.querySelector('.ap-hero-actions');
      if (!actions) return;
      var links = actions.querySelectorAll('a.ap-btn');
      rememberAndSet(document.getElementById('apBtnShareStore'), 'Share');
      rememberAndSet(links.length > 0 ? links[0] : null, 'Shop');
      rememberAndSet(links.length > 1 ? links[1] : null, 'Dashboard');
      rememberAndSet(document.getElementById('apFrLaunchBtn'), 'Fundraiser');
      rememberAndSet(document.getElementById('apFrDetailsBtn'), 'Fundraiser');
    }

    function hardenHeroRoutes() {
      var actions = document.querySelector('.ap-hero-actions');
      if (!actions) return;
      var links = actions.querySelectorAll('a.ap-btn');
      if (links[0] && window.SSAP && SSAP.collectionHandle) {
        // The server supplies the preview code when this is an unclaimed store.
        // Rebuilding this URL from only the handle silently removes that access.
        links[0].setAttribute('href', SSAP.liveStoreUrl || ('/collections/' + encodeURIComponent(SSAP.collectionHandle)));
      }
      if (links[1]) links[1].setAttribute('href', (window.SSAP && SSAP.dashboardUrl) || '/pages/portal');
    }

    function compactProductName(raw) {
      var s = String(raw || '').replace(/\s+/g, ' ').trim();
      var l = s.toLowerCase();
      if (/39165|trucker hat|snapback|\bcap\b|\bhat\b/.test(l)) return 'Trucker Hat';
      if (/full[- ]?zip/.test(l) && /hood/.test(l)) return 'Full-Zip Hoodie';
      if (/youth/.test(l) && /hood/.test(l)) return 'Youth Hoodie';
      if (/youth/.test(l) && /(tee|t-shirt|shirt)/.test(l)) return 'Youth Tee';
      if (/(women|womens|women's)/.test(l) && /(racerback|tank)/.test(l)) return "Women's Tank";
      if (/(men|mens|men's)/.test(l) && /tank/.test(l)) return "Men's Tank";
      if (/crewneck|sweatshirt|m2480/.test(l)) return 'Crewneck';
      if (/hoodie|hooded|m2580|g3719|ls14003/.test(l)) return 'Hoodie';
      if (/1717|garment[- ]?dyed/.test(l)) return 'Garment-Dyed Tee';
      if (/3413|tri[- ]?blend/.test(l)) return 'Tri-Blend Tee';
      if (/long sleeve/.test(l)) return 'Long Sleeve Tee';
      if (/racerback/.test(l)) return 'Racerback Tank';
      if (/tank|6733|1790/.test(l)) return 'Tank';
      if (/3001|tee|t-shirt|shirt/.test(l)) return 'Unisex Tee';

      var cleaned = s
        .replace(/bella\s*\+?\s*canvas/ig, '')
        .replace(/comfort colors/ig, '')
        .replace(/independent trading co\.?/ig, '')
        .replace(/cotton heritage/ig, '')
        .replace(/lane seven/ig, '')
        .replace(/next level/ig, '')
        .replace(/econscious/ig, '')
        .replace(/\b(?:bc|cc|nl|mc|ls|ec|m|g)?\d{4,5}[a-z]?\b/ig, '')
        .replace(/[|·–—-]+/g, ' ')
        .replace(/\s+/g, ' ')
        .trim();
      if (!cleaned) cleaned = s;
      return cleaned.length > 24 ? cleaned.slice(0, 22).trim() + '…' : cleaned;
    }

    function syncProductTitles() {
      document.querySelectorAll('.ap-product-title').forEach(function (el) {
        if (!el.dataset.ssFullTitle) {
          el.dataset.ssFullTitle = (el.textContent || '').trim();
          if (el.dataset.ssFullTitle) el.setAttribute('title', el.dataset.ssFullTitle);
        }
        var wanted = mq.matches ? compactProductName(el.dataset.ssFullTitle) : el.dataset.ssFullTitle;
        if ((el.textContent || '').trim() !== wanted) el.textContent = wanted;
      });
    }

    function installHeroFallbacks() {
      var share = document.getElementById('apBtnShareStore');
      var shareOverlay = document.getElementById('apShareOverlay');
      if (share && shareOverlay && !share.dataset.ssFallbackBound) {
        share.dataset.ssFallbackBound = '1';
        share.addEventListener('click', function () {
          window.setTimeout(function () {
            if (!shareOverlay.classList.contains('open')) {
              shareOverlay.classList.add('open');
              shareOverlay.setAttribute('aria-hidden', 'false');
            }
          }, 0);
        });
      }

      var fundraiser = document.getElementById('apFrLaunchBtn');
      var fundraiserOverlay = document.getElementById('apFrwOverlay');
      if (fundraiser && fundraiserOverlay && !fundraiser.dataset.ssFallbackBound) {
        fundraiser.dataset.ssFallbackBound = '1';
        fundraiser.addEventListener('click', function () {
          window.setTimeout(function () {
            if (!fundraiserOverlay.classList.contains('open')) {
              fundraiserOverlay.classList.add('open');
              fundraiserOverlay.setAttribute('aria-hidden', 'false');
              var active = fundraiserOverlay.querySelector('.ap-frw-step.ap-frw-active');
              if (!active) {
                var first = fundraiserOverlay.querySelector('.ap-frw-step');
                if (first) first.classList.add('ap-frw-active');
              }
              document.body.style.overflow = 'hidden';
            }
          }, 0);
        });
      }
    }

    function installTabFallback() {
      if (document.documentElement.dataset.ssAdminTabsFallback === '1') return;
      document.documentElement.dataset.ssAdminTabsFallback = '1';
      document.addEventListener('click', function (event) {
        var btn = event.target.closest && event.target.closest('.ap-main-tab-btn[data-main-tab]');
        if (!btn) return;
        window.setTimeout(function () {
          var targetId = btn.getAttribute('data-main-tab');
          var target = targetId && document.getElementById(targetId);
          if (!target || target.classList.contains('active')) return;
          document.querySelectorAll('.ap-main-tab-btn[data-main-tab]').forEach(function (b) {
            var on = b === btn;
            b.classList.toggle('active', on);
            b.setAttribute('aria-selected', on ? 'true' : 'false');
          });
          document.querySelectorAll('.ap-main-panel').forEach(function (panel) {
            panel.classList.toggle('active', panel === target);
          });
        }, 0);
      });
    }

    function boot() {
      syncMobileHero();
      hardenHeroRoutes();
      syncProductTitles();
      installHeroFallbacks();
      installTabFallback();
    }

    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot, { once: true });
    else boot();

