    mc1790: ['tanks'],
    ec8000: ['accessories', 'personalized'],
    hat39165: ['hats']
  };
  var activeCategory = 'all';

  function builderCategories(builder) {
    var raw = builder && (builder.categories || builder.category);
    if (Array.isArray(raw) && raw.length) return raw.map(function (item) { return String(item).toLowerCase(); });
    if (raw) return [String(raw).toLowerCase()];
    return BUILDER_CATEGORIES[builder.id] || ['more'];
  }

  /* ─── Live pricing ──────────────────────────────────────────────────────── */
  // Maps each builder to its global_pricing keys so the catalog reflects the
  // exact prices set in the Price Editor (/pages/price-editor). Falls back to
  // the hardcoded prices in each builder's `pricing` array if the live fetch
  // is unavailable.
  var PRICE_KEYS = {
    bc3413:  { front: 'BC3413_front',  back: 'BC3413_front_back' },
    bc3001y: { front: 'BC3001Y_front', back: 'BC3001Y_front_back' },
    bc3001: { front: 'BC3001_front', back: 'BC3001_front_back' },
    cc1467y: { front: 'CC1467Y_front', back: 'CC1467Y_front_back' },
    m2580:   { front: 'M2580_front',   back: 'M2580_front_back' },
    g3719:   { front: 'G3719_front',   back: 'G3719_front_back' },
    m2480:   { front: 'M2480_front',   back: 'M2480_front_back' },
    ls14003: { front: 'LS14003_front', back: 'LS14003_front_back' },
    cc1717:  { front: 'CC1717_front',  back: 'CC1717_front_back' },
    nl6733:  { front: 'NL6733_front',  back: null },
    mc1790:  { front: 'MC1790_front',  back: null },
    ec8000:  { front: 'EC8000_front',  back: 'EC8000_front_back' },
    hat39165:{ front: '39165_front',   back: null }
  };

  var livePrices = null;

  function parseDollars(s) {
    var n = parseFloat(String(s == null ? '' : s).replace(/[^0-9.]/g, ''));
    return isFinite(n) ? n : null;
  }
  function fmtPrice(n) {
    if (n == null || !isFinite(n)) return '';
    return '$' + (n % 1 === 0 ? String(n) : n.toFixed(2));
  }
  function livePrice(key, fallbackNum) {
    if (key && livePrices && livePrices[key] != null) {
      var n = Number(livePrices[key]);
      if (isFinite(n) && n > 0) return n;
    }
    return fallbackNum;
  }
  // Front price (number) for a builder — live value or hardcoded fallback.
  function frontPrice(b) {
    var keys = PRICE_KEYS[b.id] || {};
    var fb = parseDollars(b.pricing[0] && b.pricing[0].price);
    return livePrice(keys.front, fb);
  }
  // Back / front+back price (number) for a builder, or null if not offered.
  function backPrice(b) {
    var keys = PRICE_KEYS[b.id] || {};
    if (!keys.back || !b.pricing[1]) return null;
    var fb = parseDollars(b.pricing[1].price);
    return livePrice(keys.back, fb);
  }

  /* ─── Utilities ─────────────────────────────────────────────────────────── */
  function $(s) { return document.querySelector(s); }
  function ready(fn) { document.readyState === 'loading' ? document.addEventListener('DOMContentLoaded', fn, {once: true}) : fn(); }
  function ssap() { return window.SSAP || {}; }
  function esc(v) { return String(v == null ? '' : v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }

  // Fetch the live global prices once (same endpoint + auth the Price Editor
  // uses). On success, re-render so cards + modal reflect current pricing.
  function fetchLivePrices() {
    var secret = ssap()['editor' + 'Secret'] || '';
    if (!secret) return;
    fetch(RAILWAY + '/api/pricing', {
      method: 'GET',
      headers: { 'X-Editor-Secret': secret },
      cache: 'no-store'
    })
      .then(function (r) { return r.ok ? r.json() : null; })
      .then(function (data) {
        if (!data) return;
        var p = data.prices || data;
        if (p && typeof p === 'object') {
          livePrices = p;
          var c = $('#apCustomBuildersContainer');
          if (c) { c.removeAttribute('data-ss-v'); renderCards(true); }
        }
      })
      .catch(function () { /* keep hardcoded fallbacks */ });
  }

  // Product Lab (Printful_Automation's own admin page) can install a builder
  // end to end — config.py, routes.py, the editor, the build module — and
  // none of that ever reached this array, because this catalog lives in a
  // completely different repository that Product Lab has no way to touch.
  // Every product before this fetch needed BUILDERS hand-edited here first.
  //
  // This merges in anything installed there that this file does not already
  // know about, by id. An id already present keeps its hand-curated card
  // untouched — Product Lab only fills a gap, it never overrides a card
  // someone took the time to write copy for.
  function mergeDynamicCatalog(products) {
    var added = false;
    (products || []).forEach(function (p) {
      if (!p || !p.id || BUILDERS.some(function (b) { return b.id === p.id; })) return;
      BUILDERS.push({
        id: p.id,
        categories: p.categories || p.category || null,
        badge: p.badge || 'Custom Product',
        name: p.name || p.id,
        from: p.from || '',
        hint: p.hint || '',
        route: p.route,
        gallery: Array.isArray(p.gallery) ? p.gallery : [],
        desc: p.desc || '',
        specs: Array.isArray(p.specs) ? p.specs : [],
        sizes: p.sizes || '',
        colors: p.colors || '',
        pricing: Array.isArray(p.pricing) ? p.pricing : [],
      });
      var keys = p.price_keys || {};
      if (keys.front) PRICE_KEYS[p.id] = { front: keys.front, back: keys.back || null };
      added = true;
    });
    return added;
  }

  function fetchDynamicCatalog() {
    var secret = ssap()['editor' + 'Secret'] || '';
    var isDemo = !!ssap().isProspectDemo;
    if (!secret && !isDemo) return;
    var endpoint = isDemo
      ? '/apps/ss/relay/prospect/' + encodeURIComponent(ssap().shopHandle || '') + '/catalog'
      : RAILWAY + '/api/pro-builder-catalog';
    var options = {
      method: 'GET',
      cache: 'no-store'
    };
    if (!isDemo) options.headers = { 'X-Editor-Secret': secret };
    fetch(endpoint, options)
      .then(function (r) { return r.ok ? r.json() : null; })
      .then(function (data) {
        var products = data && (data.products || data);
        if (!Array.isArray(products)) return;
        var pricingChanged = false;
        if (isDemo && data.prices && typeof data.prices === 'object') {
          livePrices = data.prices;
          pricingChanged = true;
        }
        // Builders whose files are installed but whose routes the app has not
        // picked up yet. Deliberately not shown as cards — clicking one would
        // 404 — but worth saying out loud, because "I installed it and no card
        // appeared" is otherwise indistinguishable from a broken fetch.
        var pending = (data && data.pending_restart) || [];
        if (pending.length) {
          console.info('[ProBuilder] installed, waiting on an app restart before ' +
                       'they can be opened: ' + pending.join(', '));
        }
        var catalogChanged = mergeDynamicCatalog(products);
        if (catalogChanged || pricingChanged) {
          var c = $('#apCustomBuildersContainer');
          if (c) { c.removeAttribute('data-ss-v'); renderCards(true); }
          if (catalogChanged && !isDemo) fetchLivePrices();
        }
      })
      .catch(function () { /* a newly installed builder just stays invisible until this succeeds */ });
  }

  function editorUrl(b) {
    var s = ssap();
    var url = RAILWAY + b.route + '?shop_handle=' + encodeURIComponent(s.shopHandle||'') + '&' + 'sec'+'ret' + '=' + encodeURIComponent(s['editor'+'Secret']||'') + '&mode=embedded';
    if (s.shopLogoSrc) url += '&logo_url=' + encodeURIComponent(s.shopLogoSrc);
    // Always give the editor a way back to this admin page — without it, the
    // post-publish auto-close has no exit target and strands the admin in the
    // editor (worst on the new-tab fallback, where noreferrer kills history).
    url += '&return_url=' + encodeURIComponent(window.location.origin + window.location.pathname + window.location.search);
    return url;
  }

  function openEditor(url) {
    if (typeof window.apOpenEditorModal === 'function') window.apOpenEditorModal(url);
    else window.open(url, '_blank', 'noopener,noreferrer');
  }

  function showDemoMessage(message) {
    var status = document.getElementById('apStatusAddProducts');
    if (status) {
      status.textContent = message;
      status.className = 'ap-status err';
      status.scrollIntoView({behavior: 'smooth', block: 'center'});
      return;
    }
    window.alert(message);
  }

  function launch(b) {
    var s = ssap();
    if (!s.isProspectDemo) {
      openEditor(editorUrl(b));
      return;
    }
    var demo = window.SSProspectDemo || {};
    if (!demo.ready || !demo.token) {
      showDemoMessage('Your secure product preview is still loading. Please try again in a moment.');
      return;
    }
    if (demo.state && Number(demo.state.products_remaining) <= 0) {
      showDemoMessage('You created both preview products. Claim this store to keep building without limits.');
      return;
    }
    fetch('/apps/ss/relay/prospect/' + encodeURIComponent(s.shopHandle || '') + '/builder-session', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({demo_token: demo.token, model: b.id})
    })
      .then(function (response) {
        return response.json().catch(function () { return {}; }).then(function (body) {
          if (!response.ok) throw new Error(body.error || ('HTTP ' + response.status));
          return body;
        });
      })
      .then(function (body) {
        var url = String(body.editor_url || '');
        if (!url) throw new Error('The product builder URL was not returned.');
        if (s.shopLogoSrc) url += '&logo_url=' + encodeURIComponent(s.shopLogoSrc);
        openEditor(url);
      })
      .catch(function (error) {
        showDemoMessage(error.message || 'Claim your store to build more products.');
        if (demo.refresh) demo.refresh();
      });
  }

