                    <button type="button" class="sf-action-btn sf-action-btn--ghost" onclick="return clearEdited();">Remove</button>
                  {% else %}
                    <button type="button" class="sf-action-btn" onclick="return openUploaderModal();">Change</button>
                    <button type="button" class="sf-action-btn sf-action-btn--ghost" onclick="return clearAnonymousLogo();">Remove</button>
                  {% endif %}
                </div>
              </div>
            </div>

            <div class="sf-mini-status sf-hidden" id="MainLogoPending">Saving your image… please wait.</div>
          </div>

          <div id="sf-limit-msg" class="sf-error sf-hidden">You have reached the limit of 3 requests per day. Please try again tomorrow.</div>

          <div class="sf-submit-row">
            <button type="submit" id="sf-submit-btn" class="sf-btn sf-btn--solid">{% if customer %}Submit Request{% else %}Build my free preview{% endif %}</button>
          </div>

          <p class="sf-fineprint">{% if customer %}By submitting, you authorize Stella &amp; Sage to create and configure a private storefront for your group.{% else %}No account or payment required. Ordering and sharing unlock when you sign in and claim this store.{% endif %}</p>
        </div>
      </form>

      <div id="sf-provision" class="sf-hidden sf-provision">
        <div class="sf-provision-card">
          <div class="sf-spinner sf-spinner--big"></div>
          <div class="sf-provision-kicker">YOUR BUILD HAS STARTED</div>
          <div class="sf-provision-title">Your always-free store is building.</div>
          <div class="sf-provision-sub">{% if customer %}Your request is connected to your account. We’re opening the normal build flow now.{% else %}This will update with your real store to try. If you like it, sign in to claim it.{% endif %}</div>
          <div class="sf-progress"><div id="sf-progress-bar" class="sf-progress-bar"></div></div>
          <div id="sf-provision-status" class="sf-status">Securing request…</div>
          <div class="sf-provision-clock"><div><span>Usual build time</span><strong>10:00 minutes</strong></div><div><span>Time waiting</span><strong id="sf-provision-elapsed">00:00</strong></div></div>
          {% unless customer %}<p class="sf-provision-expiry">Your unclaimed store will be removed after 48 hours during overnight cleanup.</p>{% endunless %}
          {% if customer %}<div class="sf-provision-actions"><button type="button" class="sf-btn sf-btn--outline" onclick="sfCancelProvisioning()">Back</button></div>{% endif %}
        </div>
      </div>

      <div id="sf-uploader-modal" class="sf-modal sf-hidden" aria-hidden="true">
        <div class="sf-modal-backdrop" onclick="closeUploaderModal()"></div>
        <div class="sf-modal-card" role="dialog" aria-modal="true" aria-label="Studio Uploader">
          <div class="sf-modal-top">
            <div class="sf-modal-title">Studio Uploader <span id="sf-modal-slot" class="sf-modal-chip">main</span></div>
            <button type="button" class="sf-modal-x" onclick="closeUploaderModal()" aria-label="Close">✕</button>
          </div>
          <iframe id="sf-uploader-iframe" class="sf-modal-iframe" src="about:blank" title="Studio Uploader Editor" allow="clipboard-read; clipboard-write"></iframe>
          <div class="sf-modal-help">Upload your image, do quick edits, then hit <b>Done</b>. This window will close automatically.</div>
        </div>
      </div>
    </div>
</div>

<script>
  const SF_UPLOADER_BASE = "{{ studio_uploader_base_url | escape }}".replace(/\/+$/,'');
  const SF_ADMIN_EMAIL = "{{ admin_email | escape }}".toLowerCase();
  const SF_USER_EMAIL = ("{{ customer.email | escape }}").toLowerCase();
  const SF_IS_ADMIN = (SF_USER_EMAIL === SF_ADMIN_EMAIL);
  const SF_PORTAL_URL = "{{ portal_url | escape }}" || "/pages/portal";

  let sfToastTimer = null;
  let sfProvisionTimer = null;
  let sfProvisionStart = 0;
  const sfQualityState = { main: { tier: null, okToSubmit: false, hasFile: false, pending: false } };

  document.addEventListener("DOMContentLoaded", function() {
    checkRateLimit();
    wireLiveErrorClearing();
    generateHandle();
    toggleConditionals();
    updateSubmitEnabled();
  });

  function sfToastShow(msg) {
    const t = document.getElementById('sf-toast');
    const m = document.getElementById('sf-toast-msg');
    if (m && msg) m.innerHTML = msg;
    if (!t) return;
    t.classList.remove('sf-hidden');
    t.classList.add('sf-toast--show');
    if (sfToastTimer) clearTimeout(sfToastTimer);
    sfToastTimer = setTimeout(sfToastHide, 5200);
  }

  function sfToastHide() {
    const t = document.getElementById('sf-toast');
    if (!t) return;
    t.classList.remove('sf-toast--show');
    setTimeout(() => t.classList.add('sf-hidden'), 180);
  }

  function checkRateLimit() {
    if (SF_IS_ADMIN) return;
    const STORAGE_KEY = 'sf_submissions_' + new Date().toISOString().slice(0, 10);
    const count = parseInt(localStorage.getItem(STORAGE_KEY) || 0);
    if (count >= 3) {
      const btn = document.getElementById('sf-submit-btn');
      if (btn) { btn.disabled = true; btn.style.opacity = "0.5"; btn.innerText = "Daily Limit Reached"; }
      hideEl('sf-limit-msg', false);
    }
  }

  function incrementRateLimit() {
    const STORAGE_KEY = 'sf_submissions_' + new Date().toISOString().slice(0, 10);
    const count = parseInt(localStorage.getItem(STORAGE_KEY) || 0);
    localStorage.setItem(STORAGE_KEY, count + 1);
  }

  function toggleConditionals() {
    const type = document.getElementById('OrgType')?.value || "";
    const mil = document.getElementById('MilitaryBranch');
    const sport = document.getElementById('SportType');
    const branchInput = document.getElementById('BranchInput');
    const sportInput = document.getElementById('SportInput');
    if (mil) mil.classList.add('sf-hidden');
    if (sport) sport.classList.add('sf-hidden');
    if (branchInput) branchInput.required = false;
    if (sportInput) sportInput.required = false;
    if (type === 'Military Unit') { if (mil) mil.classList.remove('sf-hidden'); if (branchInput) branchInput.required = true; }
    if (type === 'Sports Team') { if (sport) sport.classList.remove('sf-hidden'); if (sportInput) sportInput.required = true; }
    updateSubmitEnabled();
  }

  function generateHandle() {
    const name = (document.getElementById('StoreName')?.value || "").trim();
    const base = name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
    const custId = (document.getElementById('SF_CUST_ID')?.value || "").toString();
    const last4 = custId ? custId.slice(-4) : "new";
    const handle = base ? (base + "-" + last4) : "";
    setText('HandlePreview', handle || '...');
    const hidden = document.getElementById('HiddenHandle');
    if (hidden) hidden.value = handle;
    updateSubmitEnabled();
  }

  function wireLiveErrorClearing() {
    const form = document.getElementById('sf-request-form');
    if (!form) return;
    const clearIfValid = (el) => {
      if (!el || !el.classList) return;
      // Picking a color swatch clears the group's error highlight.
      if (el.type === 'radio' && el.checked) {
        const group = el.closest('.sf-swatches');
        if (group) group.classList.remove('sf-field-error');
        return;
      }
      if (el.classList.contains('sf-field-error') && (el.value || '').toString().trim()) el.classList.remove('sf-field-error');
    };
    form.addEventListener('input', (e) => clearIfValid(e.target), { passive: true });
    form.addEventListener('change', (e) => clearIfValid(e.target), { passive: true });
  }

  function openUploaderModal() {
    const modal = document.getElementById("sf-uploader-modal");
    const iframe = document.getElementById("sf-uploader-iframe");
    const chip = document.getElementById("sf-modal-slot");
    if (!modal || !iframe) return false;
    if (!SF_UPLOADER_BASE) { alert("Studio Uploader URL not configured in section settings."); return false; }
    if (chip) chip.textContent = "main";
    if (modal.parentNode !== document.body) document.body.appendChild(modal);
    iframe.src = SF_UPLOADER_BASE + "/ui?embed=1&return=postmessage&slot=main";
    modal.classList.remove("sf-hidden");
    modal.setAttribute("aria-hidden", "false");
    document.body.style.overflow = "hidden";
    return false;
  }

  function closeUploaderModal() {
    const modal = document.getElementById("sf-uploader-modal");
    const iframe = document.getElementById("sf-uploader-iframe");
    if (iframe) iframe.src = "about:blank";
    if (modal) { modal.classList.add("sf-hidden"); modal.setAttribute("aria-hidden", "true"); }
    document.body.style.overflow = "";
  }

  window.addEventListener("message", async (event) => {
    const msg = event?.data;
    if (!msg || typeof msg !== "object" || msg.type !== "studio-uploader:done") return;
    try { if (event.origin !== new URL(SF_UPLOADER_BASE).origin) return; } catch (e) { return; }

    const finalizeUrl = msg.finalize_url || "";
    const directFinalImageUrl = msg.final_image_url || "";
    const sessionId = msg.session_id || "";
    const filename = msg.filename || "main_logo.png";
    const mime = msg.mime || "image/png";
    if (!finalizeUrl || !sessionId) { sfToastShow("Could not save that image. Please try again."); return; }

    setPending(true);
    try {
      const finalizeRes = await fetch(finalizeUrl, { method: "POST", headers: { "Accept": "application/json" }, cache: "no-store" });
      if (!finalizeRes.ok) throw new Error("Finalize failed " + finalizeRes.status);
      const finalizeJson = await finalizeRes.json();
      if (!finalizeJson || finalizeJson.status !== "ok") throw new Error("Finalize returned invalid response");
      let imageUrl = finalizeJson.final_image_url || directFinalImageUrl || "";
      if (!imageUrl) throw new Error("Finalize response missing final_image_url");
      imageUrl = new URL(imageUrl, SF_UPLOADER_BASE).toString();
      const file = await fileFromSavedImage(imageUrl, filename, mime);
      injectMainLogoFile(file, sessionId);
      await applyEditedPreview(file);
      closeUploaderModal();
      // The completed preview directly below already confirms the upload.
      // A second floating success box is especially distracting on mobile.
      if (document.getElementById('sf-request-form')?.dataset.signedIn === 'true') {
        sfToastShow("Logo saved. Your form is ready when you are.");
      }
    } catch (err) {
      console.error(err);
      sfToastShow("Could not save that image. Please try again.");
    } finally {
      setPending(false);
      updateSubmitEnabled();
    }
  });

  async function fileFromSavedImage(imageUrl, filename, mime) {
    const imageRes = await fetch(imageUrl + (imageUrl.includes("?") ? "&" : "?") + "t=" + Date.now(), { method: "GET", cache: "no-store" });
    if (!imageRes.ok) throw new Error("Image fetch failed " + imageRes.status);
    const blob = await imageRes.blob();
    if (!blob || blob.size === 0) throw new Error("Image fetch returned empty blob");
    return new File([blob], filename || "main_logo.png", { type: mime || blob.type || "image/png" });
  }

  function injectMainLogoFile(file, sessionId) {
    const input = document.getElementById("MainLogo");
    if (input) { const dt = new DataTransfer(); dt.items.add(file); input.files = dt.files; }
    const hs = document.getElementById("SF_MAIN_SESSION");
    if (hs) hs.value = sessionId || hs.value || "";
  }

  function setPending(on) {
    sfQualityState.main.pending = !!on;
    hideEl("MainLogoPending", !on);
    if (on) { setBadge("MainLogoBadge", "neutral", "Saving…"); setText("MainLogoQualitySub", "Please wait until the image is ready."); }
  }

  async function applyEditedPreview(file) {
    setText("MainLogoText", "✅ Ready");
    document.getElementById("MainLogoDrop")?.classList.remove("sf-field-error");
    const imgEl = document.getElementById("MainLogoPreview");
    if (imgEl && imgEl.dataset.objectUrl) { try { URL.revokeObjectURL(imgEl.dataset.objectUrl); } catch (e) {} }
    const url = URL.createObjectURL(file);
    if (imgEl) { imgEl.dataset.objectUrl = url; imgEl.src = url; }
    hideEl("MainLogoPreviewRow", false);
    hideEl("MainLogoActions", false);
    setBadge("MainLogoBadge", "neutral", "Checking…");
    setText("MainLogoQualitySub", "");
    const image = new Image();
    image.onload = () => {
      const longest = Math.max(image.naturalWidth || 0, image.naturalHeight || 0);
      let tier = "good";
      if (longest >= 3000) tier = "excellent";
      else if (longest >= 2400) tier = "good";
      else if (longest >= 1200) tier = "risky";
      else tier = "bad";
      const copy = {
        excellent: ["Excellent", "Awesome — should print great."],
        good: ["Good", "Should print fine."],
        risky: ["Good Enough", "Probably okay for simple logos, but not ideal."],
        bad: ["Bad", "Too low-quality to print cleanly. Please edit again or choose a better file."]
      };
      setBadge("MainLogoBadge", tier, copy[tier][0]);
      setText("MainLogoQualitySub", copy[tier][1]);
      sfQualityState.main.hasFile = true;
      sfQualityState.main.tier = tier;
      sfQualityState.main.okToSubmit = (tier !== "bad");
      updateSubmitEnabled();
    };
    image.onerror = () => { setBadge("MainLogoBadge", "bad", "Bad"); setText("MainLogoQualitySub", "Preview failed to load. Please try again."); sfQualityState.main = { tier: "bad", okToSubmit: false, hasFile: false, pending: false }; updateSubmitEnabled(); };
    image.src = url;
  }

  function clearEdited() {
    const input = document.getElementById("MainLogo");
    const previewImg = document.getElementById("MainLogoPreview");
    if (input) input.value = "";
    if (previewImg && previewImg.dataset.objectUrl) { try { URL.revokeObjectURL(previewImg.dataset.objectUrl); } catch (e) {} delete previewImg.dataset.objectUrl; previewImg.removeAttribute("src"); }
    sfQualityState.main = { tier: null, okToSubmit: false, hasFile: false, pending: false };
    hideEl("MainLogoPreviewRow", true);
    hideEl("MainLogoActions", true);
    hideEl("MainLogoPending", true);
    setBadge("MainLogoBadge", "neutral", "Checking…");
    setText("MainLogoQualitySub", "");
    setText("MainLogoText", "🪄 Add & edit logo");
    const hs = document.getElementById("SF_MAIN_SESSION");
    if (hs) hs.value = "";
    updateSubmitEnabled();
    return false;
  }

  function validateBeforeSubmit() {
    clearAllFieldErrors();
    hideInlineError();
    const form = document.getElementById('sf-request-form');
    if (!form) return true;
    let ok = true;
    form.querySelectorAll('[required]').forEach((el) => {
      if (el.disabled || el.closest('.sf-hidden')) return;
      const tag = el.tagName.toLowerCase();
      if (el.type === 'radio') {
        // Radio groups (the color swatches): one of the group must be checked.
        if (!form.querySelector('input[name="' + el.name + '"]:checked')) {
          markFieldError(el.closest('.sf-swatches') || el);
          ok = false;
        }
        return;
      }
      const val = (el.value || '').toString().trim();
      if ((tag === 'select' && !el.value) || ((tag === 'input' || tag === 'textarea') && !val && el.type !== 'file')) { markFieldError(el); ok = false; }
    });
    generateHandle();
    if (!(document.getElementById("HiddenHandle")?.value || "").trim()) { markFieldError(document.getElementById("StoreName")); ok = false; }
    const mainDrop = document.getElementById("MainLogoDrop");
    if (!sfQualityState.main.hasFile) { markFieldError(mainDrop); ok = false; }
    else if (sfQualityState.main.pending) { markFieldError(mainDrop); ok = false; showInlineError("Please wait — your logo is still saving."); }
    else if (sfQualityState.main.tier === "bad") { markFieldError(mainDrop); ok = false; }
    if (!ok) { sfToastShow("Please complete the required fields and add your logo."); scrollToFirstError(); }
    return ok;
  }

  function updateSubmitEnabled() {
    const btn = document.getElementById('sf-submit-btn');
    if (!btn) return;
    const isMainReady = sfQualityState.main.hasFile && !sfQualityState.main.pending && sfQualityState.main.okToSubmit;
    const hasHandle = !!(document.getElementById("HiddenHandle")?.value || "").trim();
    const STORAGE_KEY = 'sf_submissions_' + new Date().toISOString().slice(0, 10);
    const limited = (!SF_IS_ADMIN && parseInt(localStorage.getItem(STORAGE_KEY) || 0) >= 3);
    const enabled = !limited && isMainReady && hasHandle && !window.ssProductBuildingPaused;
    btn.disabled = !enabled;
    btn.style.opacity = enabled ? "1" : "0.6";
  }

  function buildDashboardRedirectUrl() {
    const handle = (document.getElementById("HiddenHandle")?.value || "").trim();
    return SF_PORTAL_URL + (handle ? ("?new_store=1&store_handle=" + encodeURIComponent(handle)) : "?new_store=1");
  }

  function startProvisioning90s() {
    const form = document.getElementById('sf-request-form');
    const provision = document.getElementById('sf-provision');
    const statusEl = document.getElementById('sf-provision-status');
    const bar = document.getElementById('sf-progress-bar');
    const header = document.querySelector('.sf-header');
    if (header) header.classList.add('sf-hidden');
    if (form) form.classList.add('sf-hidden');
    if (provision) provision.classList.remove('sf-hidden');
    if (bar) bar.style.width = '0%';
    const steps = [
      { time: 1500, text: "Securing request…" },
      { time: 11000, text: "Validating details…" },
      { time: 24000, text: "Preparing your workspace…" },
      { time: 40000, text: "Configuring access & admin controls…" },
      { time: 58000, text: "Uploading assets…" },
      { time: 72000, text: "Queuing product generation…" },
      { time: 90000, text: "<b>Success!</b> Redirecting to your dashboard…" }
    ];
    steps.forEach((s) => setTimeout(() => { if (statusEl) statusEl.innerHTML = s.text; }, s.time));
    sfProvisionStart = Date.now();
    const total = 90000;
    if (sfProvisionTimer) clearInterval(sfProvisionTimer);
    sfProvisionTimer = setInterval(() => {
      const elapsedMs = Date.now() - sfProvisionStart;
      const pct = Math.min(100, (elapsedMs / total) * 100);
      const elapsedSeconds = Math.max(0, Math.floor(elapsedMs / 1000));
      const elapsedEl = document.getElementById('sf-provision-elapsed');
      if (elapsedEl) elapsedEl.textContent = String(Math.floor(elapsedSeconds / 60)).padStart(2, '0') + ':' + String(elapsedSeconds % 60).padStart(2, '0');
      if (bar) bar.style.width = pct.toFixed(2) + '%';
      if (pct >= 100) { clearInterval(sfProvisionTimer); window.location.href = buildDashboardRedirectUrl(); }
    }, 180);
  }

  function stopProvisioning() {
    if (sfProvisionTimer) clearInterval(sfProvisionTimer);
    sfProvisionTimer = null;
    hideEl('sf-provision', true);
    document.querySelector('.sf-header')?.classList.remove('sf-hidden');
    document.getElementById('sf-request-form')?.classList.remove('sf-hidden');
  }

  function sfCancelProvisioning() {
    stopProvisioning();
    const btn = document.getElementById('sf-submit-btn');
    if (btn) { btn.disabled = false; btn.style.opacity = "1"; }
  }

  async function submitToStudioUploader(e) {
    e.preventDefault();
    const STORAGE_KEY = 'sf_submissions_' + new Date().toISOString().slice(0, 10);
    if (!SF_IS_ADMIN && parseInt(localStorage.getItem(STORAGE_KEY) || 0) >= 3) { sfToastShow("Daily limit reached."); return; }
    if (window.ssProductBuildingPaused) {
      sfToastShow("Store building is paused right now — please try again shortly.");
      updateSubmitEnabled();
      return;
    }
    generateHandle();
    if (!validateBeforeSubmit()) { window.ssJourneyEvent?.('create_validation_failed'); updateSubmitEnabled(); return; }
    if (!SF_UPLOADER_BASE) { alert("Studio Uploader URL not configured in section settings."); return; }

    const btn = document.getElementById('sf-submit-btn');
    if (btn) { btn.disabled = true; btn.style.opacity = "0.85"; }
    startProvisioning90s();

    const endpoint = SF_UPLOADER_BASE + "/api/storefront-request";
    const form = document.getElementById('sf-request-form');
    const formData = new FormData(form);

    const orgType = (document.getElementById('OrgType')?.value || "").trim();
    const sportVal = (document.getElementById('SportInput')?.value || "").trim();
    const branchVal = (document.getElementById('BranchInput')?.value || "").trim();
    let typeOfStore = "";
    if (orgType === "Sports Team" && sportVal) typeOfStore = sportVal;
    else if (orgType === "Military Unit" && branchVal) typeOfStore = branchVal;
    else if (orgType) typeOfStore = orgType;
    document.getElementById('SF_TYPE_OF_STORE').value = typeOfStore;
    if (typeOfStore) formData.set("type_of_store", typeOfStore);

    const pcVal = (document.querySelector('input[name="primary_color"]:checked')?.value || "").toString().trim();
    formData.set("primary_color", pcVal || "No preference");
    const mainInput = document.getElementById("MainLogo");
    if (!mainInput || !mainInput.files || mainInput.files.length === 0 || (mainInput.files[0] && mainInput.files[0].size === 0)) formData.delete("storefront_logo_file");
    const ms = (document.getElementById("SF_MAIN_SESSION")?.value || "").trim();
    if (!ms) formData.delete("main_session_id");
    formData.delete("secondary_session_id");
    formData.delete("storefront_logo_secondary");

    try {
      window.ssJourneyEvent?.('create_submitted');
      const res = await fetch(endpoint, { method: "POST", body: formData });
      if (!res.ok) { const t = await res.text().catch(() => ""); throw new Error("Uploader returned " + res.status + (t ? (": " + t.slice(0, 240)) : "")); }
      window.ssJourneyEvent?.('create_accepted');
      if (!SF_IS_ADMIN) incrementRateLimit();
    } catch (err) {
      window.ssJourneyEvent?.('create_failed');
      console.error(err);
      stopProvisioning();
      if (btn) { btn.disabled = false; btn.style.opacity = "1"; }
      showInlineError("We couldn't submit your request. Please double-check your details and try again.<br><span style='font-weight:700;'>Reason:</span> " + escapeHtml(err.message || "Unknown error"));
      sfToastShow("Submit failed — please review and try again.");
      scrollToInlineError();
      updateSubmitEnabled();
    }
  }

  function clearAllFieldErrors() { document.querySelectorAll('.sf-field-error').forEach(el => el.classList.remove('sf-field-error')); }
  function markFieldError(el) { if (el) el.classList.add('sf-field-error'); }
  function scrollToFirstError() { const first = document.querySelector('.sf-field-error'); if (first) first.scrollIntoView({ behavior: 'smooth', block: 'center' }); }
  function showInlineError(html) { const el = document.getElementById('sf-error-inline'); if (el) { el.innerHTML = html || "Something went wrong. Please try again."; el.classList.remove('sf-hidden'); } }
  function hideInlineError() { const el = document.getElementById('sf-error-inline'); if (el) { el.classList.add('sf-hidden'); el.innerHTML = ""; } }
  function scrollToInlineError() { const el = document.getElementById('sf-error-inline'); if (el && !el.classList.contains('sf-hidden')) el.scrollIntoView({ behavior: 'smooth', block: 'center' }); }
  function escapeHtml(str) { return (str || "").replace(/[&<>"']/g, (m) => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[m])); }
  function hideEl(id, hide) { const el = document.getElementById(id); if (el) el.classList.toggle('sf-hidden', !!hide); }
  function setText(id, text) { const el = document.getElementById(id); if (el) el.innerText = text || ""; }
  function setBadge(id, tier, text) { const el = document.getElementById(id); if (el) { el.className = "sf-badge sf-badge--" + tier; el.innerText = text; } }
</script>

{% unless customer %}
  {{ 'ss-demo-waiting-room.css' | asset_url | stylesheet_tag }}
  <section class="ss-demo-start" data-ss-demo-start data-embedded="true" data-enabled="true" data-api-base="{{ anonymous_preview_api_base_url | escape }}" data-permanent-url="/pages/request-storefront-form" hidden>
    <div class="ss-demo-start__shell">{% render 'ss-demo-wait-content' %}</div>
  </section>
  <script src="{{ 'ss-anonymous-demo-start.js' | asset_url }}" defer></script>
  <script src="{{ 'ss-anonymous-request-form.js' | asset_url }}" defer></script>
{% endunless %}

<style>
  .sf-container { max-width: 720px; margin: 56px auto; padding: 0 18px; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; }
  .sf-header { text-align: center; margin-bottom: 24px; }
  .sf-h1 { font-size: 30px; font-weight: 900; margin-bottom: 8px; color: #111; letter-spacing: -0.02em; }
  .sf-sub { font-size: 15px; color: #666; margin: 0; }
  .sf-form-wrap { background: #fff; border: 1px solid rgba(0,0,0,0.08); border-radius: 20px; padding: 24px; box-shadow: 0 10px 40px rgba(0,0,0,0.04); position: relative; }
  .sf-auth-card { text-align:center; padding: 18px 4px; }
  .sf-auth-icon { width: 58px; height: 58px; margin: 0 auto 14px; border-radius: 18px; display:flex; align-items:center; justify-content:center; background:#f4f4f5; font-size:28px; }
  .sf-auth-title { margin: 0 0 10px; font-size: 24px; font-weight: 950; letter-spacing: -0.03em; color:#111; }
  .sf-auth-text { max-width: 560px; margin: 0 auto 22px; color:#64748b; font-size: 15px; line-height: 1.55; }
  .sf-auth-actions { display:grid; gap: 10px; max-width: 430px; margin: 0 auto; }
  .sf-entry-choice { margin: 0 0 14px; padding: 13px 16px; border: 1px solid rgba(183,163,106,.38); border-radius: 16px; background: #fbf8ef; display: flex; align-items: center; justify-content: space-between; gap: 18px; }
  .sf-entry-choice div { display: grid; gap: 2px; }
  .sf-entry-choice strong { color: #191711; font-size: 13px; }
  .sf-entry-choice span { color: #706a5d; font-size: 12px; line-height: 1.4; }
  .sf-entry-choice a { flex: 0 0 auto; border: 1px solid rgba(23,21,15,.18); border-radius: 999px; padding: 9px 13px; background: #fff; color: #17150f; font-size: 12px; font-weight: 850; text-decoration: none; }
  .sf-block { padding: 4px 0; }
  .sf-divider { height: 1px; background: linear-gradient(90deg, rgba(183,163,106,0.35), rgba(0,0,0,0.06) 40%); margin: 22px 0; }
  .sf-legend { font-size: 12px; text-transform: uppercase; letter-spacing: 0.12em; font-weight: 800; color: #8a7a4f; margin-bottom: 14px; display: flex; align-items: center; gap: 8px; }
  .sf-legend::before { content: ''; width: 18px; height: 2px; border-radius: 2px; background: #b7a36a; }

  /* ── Color swatch picker ─────────────────────────────────────────────── */
  .sf-swatches { display: grid; grid-template-columns: repeat(auto-fill, minmax(74px, 1fr)); gap: 10px 6px; }
  .sf-sw { display: flex; flex-direction: column; align-items: center; gap: 5px; cursor: pointer; padding: 7px 2px 6px; border-radius: 12px; border: 1.5px solid transparent; transition: background .15s ease, border-color .15s ease; }
  .sf-sw:hover { background: #f7f5f0; }
  .sf-sw input { position: absolute; opacity: 0; pointer-events: none; }
  .sf-sw-dot { width: 34px; height: 34px; border-radius: 50%; background: var(--sw); box-shadow: inset 0 -2px 5px rgba(0,0,0,0.14); transition: transform .12s ease, box-shadow .15s ease; }
  .sf-sw-dot--light { border: 1px solid #ddd; }
  .sf-sw-dot--earthy { background: conic-gradient(#ece5d5 0 25%, #c8b088 0 50%, #8b8d8e 0 75%, #5f5849 0); }
  .sf-sw-dot--any { background: #fff; border: 2px dashed #cbb; display: flex; align-items: center; justify-content: center; font-weight: 900; color: #b7a36a; font-size: 15px; }
  .sf-sw-name { font-size: 10.5px; font-weight: 800; color: #666; letter-spacing: 0.01em; white-space: nowrap; }
  .sf-sw input:checked ~ .sf-sw-dot { transform: scale(1.12); box-shadow: 0 0 0 3px #fff, 0 0 0 6px #b7a36a, inset 0 -2px 5px rgba(0,0,0,0.14); }
  .sf-sw input:checked ~ .sf-sw-name { color: #111; }
  .sf-sw:has(input:checked) { border-color: rgba(183,163,106,0.55); background: rgba(183,163,106,0.08); }
  .sf-sw input:focus-visible ~ .sf-sw-dot { outline: 2px solid #0f172a; outline-offset: 3px; }
  .sf-sw--wide .sf-sw-name { white-space: normal; text-align: center; line-height: 1.15; font-size: 10px; }
  /* Color picker owns the right column of Step 1 (spanning the rows) so the
     Store Type + conditional sport/branch + Storefront Name stack on the
     left and never reflow it. */
  .sf-field--color { grid-column: 2; grid-row: 1 / span 3; }
  @media (max-width: 720px) { .sf-field--color { grid-column: auto; grid-row: auto; } }
  .sf-swatches.sf-field-error { border: 1.5px solid #dc2626 !important; border-radius: 14px; padding: 8px; background: #fff6f6; box-shadow: 0 0 0 3px rgba(220,38,38,0.10) !important; }
  .sf-grid { display: grid; gap: 14px; grid-template-columns: 1fr 1fr; }
  @media(max-width: 680px) { .sf-grid { grid-template-columns: 1fr; } }
  .sf-field { margin-bottom: 0; }
  .sf-label { display: block; font-weight: 800; font-size: 13px; margin-bottom: 8px; color: #333; }
  .sf-input, .sf-select { width: 100%; padding: 12px 14px; border: 1px solid #ddd; border-radius: 12px; font-size: 16px; transition: all 0.2s; background: #fafafa; color: #333; }
  .sf-input:focus, .sf-select:focus { border-color: #111; background: #fff; outline: none; }
  .sf-help { font-size: 12px; color: #888; margin-top: 6px; }
  .sf-mono { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; color: #111; background: #eee; padding: 2px 6px; border-radius: 6px; }
  .sf-file-drop { border: 2px dashed #ddd; border-radius: 14px; padding: 22px; text-align: center; cursor: pointer; transition: all 0.2s; background: #fafafa; position: relative; font-weight: 900; }
  .sf-file-drop:hover { border-color: #999; background: #f0f0f0; }
  .sf-file-input { display: none; }
  .sf-preview-row { margin-top: 12px; display: flex; gap: 12px; align-items: flex-start; padding: 12px; border: 1px solid #eee; border-radius: 14px; background: #fafafa; }
  .sf-preview-img { width: 74px; height: 74px; border-radius: 14px; object-fit: contain; background: #fff; border: 1px solid #e6e6e6; }
  .sf-preview-meta { flex: 1; }
  .sf-badge-row { display: flex; align-items: center; gap: 10px; margin-bottom: 6px; }
  .sf-badge { display: inline-flex; align-items: center; padding: 6px 10px; border-radius: 999px; font-weight: 900; font-size: 12px; letter-spacing: 0.02em; border: 1px solid rgba(0,0,0,0.08); background: #fff; }
  .sf-badge--neutral { color: #444; background: #fff; }
  .sf-badge--excellent { color: #0b2a6b; background: #e8f0ff; border-color: rgba(11,42,107,0.18); }
  .sf-badge--good { color: #0f4d2a; background: #e8f8ef; border-color: rgba(15,77,42,0.18); }
  .sf-badge--risky { color: #6a4a00; background: #fff6db; border-color: rgba(106,74,0,0.18); }
  .sf-badge--bad { color: #7a0b0b; background: #ffe8e8; border-color: rgba(122,11,11,0.18); }
  .sf-quality-sub { font-size: 12px; color: #666; margin-bottom: 10px; line-height: 1.35; }
  .sf-actions { display: flex; gap: 10px; flex-wrap: wrap; }
  .sf-action-btn { appearance: none; border: 1px solid #ddd; background: #fff; color: #111; font-weight: 900; font-size: 12px; padding: 10px 12px; border-radius: 999px; cursor: pointer; transition: transform .08s ease, border-color .2s ease; }
  .sf-action-btn:hover { border-color: #bbb; transform: translateY(-1px); }
  .sf-action-btn--ghost { background: transparent; }
  .sf-mini-status { margin-top: 10px; font-size: 12px; color: #64748b; font-weight: 800; display: inline-flex; align-items: center; gap: 8px; }
  .sf-mini-status::before { content: ""; width: 14px; height: 14px; border: 2px solid rgba(15,23,42,0.18); border-top-color: #0f172a; border-radius: 999px; display: inline-block; animation: sfspin 1s linear infinite; }
  .sf-hidden { display: none !important; }
  .sf-submit-row { margin-top: 18px; }
  .sf-btn { width: 100%; background: #111; color: #fff; border: none; padding: 14px 16px; border-radius: 999px; font-size: 16px; font-weight: 900; cursor: pointer; transition: transform 0.1s; text-decoration: none; display: inline-flex; align-items: center; justify-content: center; }
  .sf-btn:hover { transform: translateY(-1px); background: #000; color: #fff; }
  .sf-btn--solid { background:#0f172a; }
  .sf-btn--outline { background: transparent; border: 2px solid #111; color: #111; }
  .sf-fineprint { margin: 14px 0 0; font-size: 12px; color: #94a3b8; text-align: center; line-height: 1.35; }
  .sf-error { background: #fee; color: #c00; padding: 14px 14px; border-radius: 12px; margin-bottom: 16px; text-align: center; font-weight: 800; border: 1px solid rgba(220, 38, 38, 0.18); }
  .sf-field-error { border-color: #dc2626 !important; box-shadow: 0 0 0 3px rgba(220, 38, 38, 0.10) !important; background: #fff !important; }
  .sf-file-drop.sf-field-error { border-color: #dc2626 !important; background: #fff6f6 !important; }
  .sf-toast { position: fixed; left: 50%; bottom: 18px; transform: translateX(-50%); z-index: 9999; width: min(720px, calc(100% - 24px)); pointer-events: none; }
  .sf-toast-inner { pointer-events: auto; background: #0f172a; color: #fff; border-radius: 14px; padding: 12px 14px; display: flex; align-items: center; justify-content: space-between; gap: 14px; box-shadow: 0 18px 50px rgba(15,23,42,0.25); opacity: 0; transform: translateY(8px); transition: opacity .16s ease, transform .16s ease; }
  .sf-toast--show .sf-toast-inner { opacity: 1; transform: translateY(0); }
  .sf-toast-msg { font-size: 13px; line-height: 1.35; }
  .sf-toast-x { appearance: none; border: none; background: rgba(255,255,255,0.12); color: #fff; width: 34px; height: 34px; border-radius: 10px; cursor: pointer; font-size: 16px; font-weight: 900; }
  .sf-provision { padding: 10px 0 0; }
  .sf-provision-card { background: #fff; border: 1px solid rgba(0,0,0,0.08); border-radius: 24px; padding: 36px 22px; box-shadow: 0 10px 40px rgba(0,0,0,0.06); text-align: center; }
  .sf-provision-title { font-size: 18px; font-weight: 900; color: #0f172a; margin: 6px 0 6px; letter-spacing: -0.01em; }
  .sf-provision-kicker { color:#8a7745; font-size:10px; font-weight:900; letter-spacing:.13em; margin:4px 0 7px; }
  .sf-provision-sub { font-size: 13px; color: #64748b; margin-bottom: 18px; }
  .sf-progress { width: 100%; height: 8px; border-radius: 999px; background: #eef2f7; overflow: hidden; margin: 18px 0 14px; }
  .sf-progress-bar { width: 0%; height: 100%; background: #0f172a; border-radius: 999px; transition: width .18s linear; }
  .sf-status { margin-top: 6px; font-size: 13px; color: #64748b; min-height: 24px; transition: opacity .28s ease; opacity: 1; }
  .sf-status b { color: #10b981; }
  .sf-spinner { width: 18px; height: 18px; border: 3px solid rgba(15,23,42,0.18); border-top-color: #0f172a; border-radius: 50%; animation: sfspin 1s linear infinite; display: inline-block; vertical-align: middle; }
  .sf-spinner--big { width: 44px; height: 44px; border-width: 4px; margin: 0 auto 14px; display: block; }
  @keyframes sfspin { to { transform: rotate(360deg); } }
  .sf-provision-actions { margin-top: 16px; display: flex; justify-content: center; }
  .sf-provision-clock { display:grid; grid-template-columns:1fr 1fr; gap:9px; margin:15px auto 0; max-width:430px; }
  .sf-provision-clock>div { display:grid; gap:3px; padding:11px; border:1px solid #e5dfd0; border-radius:12px; background:#fbf8ef; }
  .sf-provision-clock span { color:#81765d; font-size:9px; font-weight:850; letter-spacing:.08em; text-transform:uppercase; }
  .sf-provision-clock strong { color:#17150f; font-size:16px; font-variant-numeric:tabular-nums; }
  .sf-provision-expiry { margin:12px auto 0; color:#7b7468; font-size:11px; line-height:1.45; }
  .sf-modal { position: fixed; inset: 0; z-index: 10000; display: flex; align-items: center; justify-content: center; }
  .sf-modal-backdrop { position: absolute; inset: 0; background: rgba(15,23,42,0.45); backdrop-filter: blur(6px); }
  .sf-modal-card { position: relative; width: min(1100px, calc(100% - 24px)); height: min(680px, calc(100vh - 24px)); margin: 12px auto; background: #0b1220; border: 1px solid rgba(255,255,255,0.12); border-radius: 18px; overflow: hidden; box-shadow: 0 25px 90px rgba(0,0,0,0.40); display: flex; flex-direction: column; }
  .sf-modal-top { display: flex; align-items: center; justify-content: space-between; padding: 12px 14px; background: rgba(255,255,255,0.04); border-bottom: 1px solid rgba(255,255,255,0.10); color: #fff; }
  .sf-modal-title { font-weight: 900; letter-spacing: -0.01em; display: flex; align-items: center; gap: 10px; }
  .sf-modal-chip { display: inline-flex; align-items: center; justify-content: center; padding: 6px 10px; border-radius: 999px; font-size: 12px; background: rgba(255,255,255,0.08); color: rgba(255,255,255,0.8); }
  .sf-modal-x { appearance: none; border: none; background: rgba(255,255,255,0.08); color: #fff; width: 36px; height: 36px; border-radius: 10px; cursor: pointer; font-size: 18px; font-weight: 900; }
  .sf-modal-iframe { width: 100%; flex: 1; border: 0; background: #fff; }
  .sf-modal-help { padding: 10px 14px; font-size: 12px; color: rgba(255,255,255,0.72); background: rgba(255,255,255,0.04); border-top: 1px solid rgba(255,255,255,0.10); }
  @media(max-width: 680px) { .sf-container { margin: 30px auto; } .sf-form-wrap { padding: 18px; border-radius: 18px; } .sf-entry-choice { align-items: stretch; flex-direction: column; gap: 10px; } .sf-entry-choice a { text-align: center; } .sf-modal-card { height: calc(100vh - 16px); width: calc(100% - 16px); } }
</style>

{% schema %}
{
  "name": "Store Request Form",
  "settings": [
    {
      "type": "text",
      "id": "studio_uploader_base_url",
      "label": "Studio Uploader Base URL (Railway)",
      "default": "https://studio-uploader-production.up.railway.app"
    },
    {
      "type": "text",
      "id": "anonymous_preview_api_base_url",
      "label": "Anonymous Preview API URL",
      "default": "https://anonymous-demo-preview-production.up.railway.app"
    },
    {
      "type": "text",
      "id": "admin_email",
      "label": "Admin Email (Unlimited Requests)",
      "default": "ryan.irwin@stellaandsagecompany.com"
    },
    {
      "type": "text",
      "id": "portal_url",
      "label": "Dashboard URL",
      "default": "/pages/portal"
    }
  ],
  "presets": [
    { "name": "Store Request Form (Dashboard Login Pattern)" }
  ]
}
{% endschema %}

{% comment %}
  PRIVATE STORE HERO — PREMIUM STOREFRONT V3
  - Desktop: premium full hero.
  - Mobile: ultra-compact shopping-first hero so products appear immediately.
  - Keeps member/admin access logic.
  - Adds admin-only Admin Powers link on desktop + mobile.
  - Adds admin-only Share Store popup with copy link + QR code.
  - Keeps product grid logo overlay logic from previous section.
{% endcomment %}

{% assign handle = collection.handle | downcase | strip %}
{% assign member_tag = 'storefront-member--' | append: handle %}
{% assign admin_tag  = 'storefront-admin--'  | append: handle %}
{% capture ps_access %}{% render 'private-store-access', handle: handle %}{% endcapture %}
{% assign ps_access = ps_access | strip %}
{% assign is_admin = false %}
{% assign allowed = false %}
{% assign is_preview = false %}
{% if ps_access == 'admin' %}{% assign is_admin = true %}{% assign allowed = true %}{% endif %}
{% if ps_access == 'member' %}{% assign allowed = true %}{% endif %}
{% if ps_access == 'preview' %}{% assign allowed = true %}{% assign is_preview = true %}{% endif %}

{% assign entry = shop.metaobjects.custom_shop[handle] %}
{% assign store_name = collection.title %}
{% assign store_logo = blank %}
{% assign join_mode = 'secure' %}
{% assign join_code = '' %}
{% assign prospect_owner = '' %}

{% if entry %}
  {% assign n = entry.name.value | default: entry.name %}
  {% if n != blank %}{% assign store_name = n %}{% endif %}

  {% assign l = entry.logo.value | default: entry.logo %}
  {% if l != blank %}{% assign store_logo = l %}{% endif %}

  {% assign raw_jm = entry.join_mode.value | default: entry.join_mode %}
  {% assign jm = raw_jm | strip | downcase %}
  {% if jm == 'public' %}{% assign join_mode = 'public' %}{% endif %}

  {% assign join_code = entry.join_code.value | default: entry.join_code | default: '' | strip %}
  {% assign prospect_owner = entry.owner_customer_id.value | default: entry.owner_customer_id | default: '' | strip | downcase %}
{% endif %}

{% assign logo_url = store_logo | image_url: width: 400 %}
{% assign join_link = shop.url | append: '/pages/join-store?shop=' | append: handle %}
{% if join_code != blank %}
  {% assign join_link = join_link | append: '&code=' | append: join_code %}
{% endif %}

<span hidden data-ss-store-access="{{ ps_access | escape }}" data-ss-store-handle="{{ handle | escape }}"></span>
{{ 'ss-mobile-product-cards.css' | asset_url | stylesheet_tag }}

{% if allowed %}

  {% render 'storefront-activity-tracker', handle: handle %}

  {%- if is_preview -%}
    {%- comment -%}
      What a prospect sees first. They arrived from a cold email, so the page
      has to say what this is and what happens next before they wonder.
    {%- endcomment -%}
    <div class="ps-preview-banner">
      <div class="ps-preview-banner__inner">
        <span class="ps-preview-banner__label">Live preview</span>
        <span class="ps-preview-banner__text">
          This is a working store built for {{ store_name }}. Open any product to pick
          colors, sizes and add a name &amp; number. Nothing here is public.
        </span>
        {%- comment -%}
          Joining has to be reachable from wherever the visitor is convinced,
          which is in here looking at the gear — not back on the card they
          clicked through a minute ago.
        {%- endcomment -%}
        {%- comment -%}
          Try the admin lives in the Store actions card under Shop products, not
          here. Two gold pills in a thin strip read as an ad; one clear next step
          reads as a store.

          The label matches the one in Store actions exactly. It is the same
          link, and calling it "Join" up here while calling it "Claim" down
          there made one action look like two different offers.
        {%- endcomment -%}
        <a class="ps-preview-banner__cta" href="{{ join_link }}">
          {% if prospect_owner == 'unclaimed' %}Claim this store{% else %}Join this store{% endif %}
        </a>
      </div>
    </div>
    <style>
      .ps-preview-banner { padding: 10px 16px 0; }
      .ps-preview-banner__inner {
        display: flex; flex-wrap: wrap; align-items: center; gap: 12px;
        max-width: 1200px; margin: 0 auto; padding: 12px 16px;
        background: rgb(17 16 14 / 0.92); color: #fff; border-radius: 12px;
        font-size: 14px; line-height: 1.4;
      }
      .ps-preview-banner__label {
        font-size: 11px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase;
        background: rgba(183,163,106,.9); color: #1a160c; padding: 4px 9px; border-radius: 999px;
        white-space: nowrap;
      }
      .ps-preview-banner__text { flex: 1 1 260px; }
      .ps-preview-banner__cta {
        background: #fff; color: #17150f; text-decoration: none; font-weight: 700;
        padding: 9px 16px; border-radius: 999px; white-space: nowrap;
      }
    </style>
    {% render 'private-store-preview-links', handle: handle %}
    {% if prospect_owner == 'unclaimed' %}
      <script src="{{ 'ss-prospect-store-demo.js' | asset_url }}" defer></script>
    {% endif %}
  {%- endif -%}


  {% if is_admin %}
    <script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script>
  {% endif %}

  <section class="ps-hero" id="ps-storefront-{{ section.id }}">
    <div class="ps-shell">
      <div class="ps-hero-card">

        <div class="ps-hero-main">
          {% render 'logo-frame-contrast' %}
          <div class="ps-logo">
            {% if store_logo != blank %}
              {{ store_logo | image_url: width: 520 | image_tag: class: 'ps-logo-img', loading: 'eager', alt: store_name }}
            {% else %}
              <span class="ps-logo-fallback">{{ store_name | slice: 0, 1 | upcase }}</span>
            {% endif %}
          </div>

          <div class="ps-copy">
            <div class="ps-eyebrow">
              <span class="ps-live-dot"></span>
              Private Storefront
            </div>

            <h1 class="ps-title">{{ store_name }}</h1>

            <p class="ps-sub">
              Approved gear for your group. Choose your size, checkout directly, and come back anytime for reorders.
            </p>

            <div class="ps-meta-row">
              <span>{{ collection.products_count }} {% if collection.products_count == 1 %}item{% else %}items{% endif %}</span>
              <span>Direct checkout</span>
              <span>Reorder anytime</span>
            </div>
          </div>
        </div>

        <div class="ps-action-panel">
          <div class="ps-action-panel-title">Store actions</div>

          <a class="ps-btn ps-btn-solid ps-shop-anchor" href="#ProductGridContainer">
            Shop products ↓
          </a>

          {%- comment -%}
            Second only to shopping, because trying the admin is what turns a
            visitor into a claim. Liquid only renders it for a preview of a live
            unclaimed store, so it is present immediately instead of appearing
            late after a relay request.
          {%- endcomment -%}
          {% if is_preview and prospect_owner == 'unclaimed' %}
            <div class="ps-demo-cta" data-ss-prospect-demo-wrap>
              <a class="ps-btn ps-btn-demo"
                 href="/pages/admin-powers?shop={{ handle | url_encode }}&prospect_demo=1"
                 data-ss-prospect-demo-cta
                 data-shop-handle="{{ handle | escape }}"
                 data-claim-url="{{ join_link | escape }}"
                 aria-describedby="psDemoNote-{{ section.id }}">
                Admin Powers
              </a>
              <span class="ps-demo-note" id="psDemoNote-{{ section.id }}" role="tooltip">
                Look around the admin without signing in. Build a product and change
                how the store looks.
              </span>
            </div>
          {% endif %}

          {%- comment -%}
            One word for one action. On an unclaimed store this link makes the
            first person to use it the administrator, which is claiming, not
            joining — and "Claim store" beside "Join this store" read as two
            different offers when they were always the same link. Once the store
            has an owner the same link really does only add a member, so the
            label goes back to joining.
          {%- endcomment -%}
          {% if is_preview %}
            <a class="ps-btn ps-btn-ghost" href="{{ join_link }}">
              {% if prospect_owner == 'unclaimed' %}Claim this store{% else %}Join this store{% endif %}
            </a>
          {% else %}
            <a class="ps-btn ps-btn-ghost" href="/pages/portal">
              ← Dashboard
            </a>
          {% endif %}

          {% if is_admin %}
            <button class="ps-btn ps-btn-soft" id="psShareStoreBtn" type="button">
              🔗 Share Store
            </button>

            <a class="ps-btn ps-btn-admin" href="/pages/admin-powers?shop={{ handle | url_encode }}">
              Admin Powers
            </a>
          {% endif %}
        </div>

      </div>

      {% if is_admin %}
        <div class="ps-admin-mobile-bar" aria-label="Admin quick actions">
          <button class="ps-mobile-pill" id="psShareStoreBtnMobile" type="button">🔗 Share</button>
          <a class="ps-mobile-pill ps-mobile-pill--dark" href="/pages/admin-powers?shop={{ handle | url_encode }}">Admin</a>
        </div>
      {% endif %}
    </div>
  </section>

  {% if is_admin %}
    <div class="ps-share-overlay" id="psShareOverlay" aria-hidden="true">
      <div class="ps-share-dialog" role="dialog" aria-modal="true" aria-labelledby="psShareTitle">
