                            </button>
                          {% endif %}

                          {% unless tile_is_admin %}
                            {% if is_fully_ready %}
                              <button
                                class="ss-leave-btn"
                                data-leave-store
                                data-handle="{{ handle | escape }}"
                                data-name="{{ tile_name | escape }}">
                                Leave Store
