                            {% endif %}
                          {% endunless %}
                        {% endif %}

                      </div>

                      <!-- Active fundraiser strip (revealed by JS when a fundraiser is live) -->
                      <div class="ss-fr-strip" data-ss-fr-strip style="display:none;">
                        <div class="ss-fr-strip-head">
