    --ss-gray: #5b6b82;
    --ss-accent: #2b6de8;
    --ss-success: #10b981;
    --ss-qa: #7c3aed;

    --ss-card: rgba(255,255,255,0.78);
    --ss-border: rgba(15,23,42,0.07);
    --ss-shadow-card: 0 10px 24px rgba(15, 23, 42, 0.05);
    --ss-shadow-hover: 0 18px 40px rgba(15, 23, 42, 0.08);
    --ss-glow: 0 0 0 1px rgba(43, 109, 232, 0.08), 0 10px 26px rgba(43, 109, 232, 0.06);
  }

  .ss-portal { font-family: var(--ss-font); color: var(--ss-dark); -webkit-font-smoothing: antialiased; }
  .ss-bg {
    background: radial-gradient(circle at 50% 0%, #f8fafc 0%, #e9eef6 55%, #edf1f7 100%);
    min-height: 85vh;
    padding: 54px 0;
  }
  .ss-wrap { max-width: 1100px; margin: 0 auto; padding: 0 24px; }

  .ss-header {
    display: flex; justify-content: space-between; align-items: flex-end;
    margin-bottom: 18px; padding-bottom: 16px;
    border-bottom: 1px solid rgba(15,23,42,0.06);
  }
  .ss-h1 { font-size: 30px; font-weight: 800; letter-spacing: -0.035em; margin: 0; }
  .ss-sub { font-size: 14px; color: var(--ss-gray); margin: 6px 0 0 0; }

  .ss-seller-alert {
    background: #f0fdf4; border: 1px solid #bbf7d0; border-radius: 12px;
    padding: 15px 20px; margin-bottom: 24px; display: flex;
    justify-content: space-between; align-items: center;
    box-shadow: 0 4px 6px -1px rgba(0,0,0,0.05);
  }
  .ss-seller-content { display: flex; gap: 15px; align-items: center; }
  .ss-seller-icon { font-size: 20px; background: #dcfce7; width: 40px; height: 40px; display: flex; align-items: center; justify-content: center; border-radius: 50%; }
  .ss-seller-text strong { display: block; color: #166534; font-size: 15px; }
  .ss-seller-text p { margin: 0; color: #15803d; font-size: 13px; }
  .ss-btn-seller {
    background: #166534; color: #fff !important; padding: 10px 20px;
    border-radius: 8px; text-decoration: none; font-weight: 600;
    transition: 0.2s; white-space: nowrap;
  }
  .ss-btn-seller:hover { background: #14532d; transform: translateY(-1px); }

  @media (max-width: 600px) {
    .ss-seller-alert { flex-direction: column; gap: 15px; text-align: center; }
    .ss-seller-content { flex-direction: column; }
    .ss-btn-seller { width: 100%; display: block; text-align: center; }
  }

  .ss-user-pill {
    display: flex; align-items: center; gap: 12px;
    background: rgba(255,255,255,0.70);
    padding: 6px 10px 6px 6px;
    border-radius: 999px;
    border: 1px solid var(--ss-border);
    box-shadow: var(--ss-shadow-card);
    backdrop-filter: blur(10px);
  }
  .ss-avatar {
    width: 36px; height: 36px;
    background: linear-gradient(180deg, #0f172a 0%, #111827 100%);
    color: #fff;
    border-radius: 50%;
    display: flex; align-items: center; justify-content: center;
    font-weight: 800;
    font-size: 14px;
    box-shadow: 0 8px 16px rgba(15, 23, 42, 0.14);
  }
  .ss-user-meta { display: flex; flex-direction: column; line-height: 1.12; margin-right: 6px; }
  .ss-user-name { font-size: 13px; font-weight: 750; }
  .ss-user-status { font-size: 10px; font-weight: 700; color: var(--ss-success); text-transform: uppercase; letter-spacing: 0.06em; }

  .ss-pill-btn {
    text-decoration: none;
    font-size: 12px;
    font-weight: 750;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: var(--ss-dark);
    background: rgba(15, 23, 42, 0.05);
    border: 1px solid rgba(15, 23, 42, 0.08);
    padding: 10px 14px;
    border-radius: 999px;
    transition: 0.18s ease;
    white-space: nowrap;
  }

  .ss-main { display: flex; flex-direction: column; gap: 18px; }
  .ss-block { width: 100%; }

  .ss-hero {
    display: grid;
    grid-template-columns: 1.15fr 0.85fr;
    gap: 14px;
  }
  .ss-hero-left, .ss-hero-right {
    background: var(--ss-card);
    border: 1px solid var(--ss-border);
    border-radius: 22px;
    box-shadow: var(--ss-shadow-card);
    backdrop-filter: blur(10px);
  }
  .ss-hero-left { padding: 20px; }
  .ss-hero-right { padding: 16px; display: flex; flex-direction: column; gap: 12px; }

  .ss-hero-kicker {
    display: inline-flex;
    align-items: center;
    font-size: 10px;
    font-weight: 750;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    color: rgba(43, 109, 232, 0.95);
    background: rgba(43, 109, 232, 0.07);
    border: 1px solid rgba(43, 109, 232, 0.10);
    padding: 8px 12px;
    border-radius: 999px;
    margin-bottom: 12px;
  }
  .ss-hero-title {
    font-size: 18px;
    font-weight: 820;
    letter-spacing: -0.025em;
    margin: 0 0 8px 0;
    max-width: 44ch;
  }
  .ss-hero-sub {
    font-size: 13px;
    color: var(--ss-gray);
    line-height: 1.55;
    margin: 0 0 14px 0;
    max-width: 60ch;
  }
