  /* Active fundraiser strip (full-width row across the bottom of a store card) */
  .ss-store-card.ss-card-has-fr { flex-wrap: wrap; }
  .ss-fr-strip {
    flex-basis: 100%; width: 100%;
    margin-top: 14px; padding-top: 14px;
    border-top: 1px solid rgba(15,23,42,0.08);
    display: flex; flex-direction: column; gap: 10px;
  }
  .ss-fr-strip-head { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
  .ss-fr-pill {
    display: inline-flex; align-items: center; gap: 6px;
    font-size: 10.5px; font-weight: 850; letter-spacing: 0.06em; text-transform: uppercase;
    color: #166534; background: rgba(22,163,74,0.10);
    border: 1px solid rgba(22,163,74,0.22); padding: 4px 10px; border-radius: 999px;
  }
  /* The pulse rides on a pseudo-element using transform + opacity, which the
     compositor can animate on its own. Animating box-shadow repaints the dot
     every frame, and with a pulse on every visible card that repaint work
     lands on the same thread doing the scrolling. */
  .ss-fr-dot {
    position: relative;
    width: 7px; height: 7px; border-radius: 50%; background: #16a34a;
  }
  .ss-fr-dot::after {
    content: ''; position: absolute; inset: 0; border-radius: 50%;
    background: rgba(22,163,74,0.5);
    animation: ssFrPulse 2s infinite;
    will-change: transform, opacity;
  }
  @keyframes ssFrPulse {
    0%   { transform: scale(1);   opacity: 0.5; }
    70%  { transform: scale(2.7); opacity: 0; }
    100% { transform: scale(2.7); opacity: 0; }
  }
  /* Respect a reduced-motion preference — an infinite pulse per card is a lot
     of movement for anyone who has asked for less of it. */
  @media (prefers-reduced-motion: reduce) {
    .ss-fr-dot::after { animation: none; opacity: 0; }
  }
