      gap: 10px;
      flex-wrap: wrap;
      margin: 6px 0 14px;
      padding: 0 2px;
    }
    .ss-mobile-insights { display: block; }

    /* ── Card: compact, single-padding layout with tidy stacked sections ── */
    .ss-store-card {
      flex-direction: column;
      align-items: stretch;
      gap: 12px;
      padding: 14px;
      border-radius: 20px;
      overflow: hidden;
    }

    /* Header: logo + name aligned together */
    .ss-col-identity {
      width: 100%;
      gap: 12px;
      padding: 0;
      align-items: center;
    }
    .ss-logo-frame {
      width: 60px;
      height: 60px;
