    .ss-card-title { font-size: 16px; font-weight: 820; letter-spacing: -0.02em; }
    .ss-card-subtitle { font-size: 11px; margin-top: 3px; }

    /* Status badge: own line, left aligned, compact */
    .ss-col-engine {
      width: 100%;
      padding: 0;
      justify-content: flex-start;
    }

    /* Controls: aligned button row that shares space evenly */
    .ss-col-controls {
      width: 100%;
      display: flex;
      flex-direction: row;
      flex-wrap: wrap;
      align-items: center;
      gap: 10px;
      padding: 12px 0 0;
      border-top: 1px solid rgba(15,23,42,0.07);
    }
    /* Primary action buttons share the row equally and stay aligned */
    .ss-col-controls > .ss-admin-btn,
    .ss-col-controls > .ss-open-btn,
    .ss-col-controls > .ss-wake-btn {
      flex: 1 1 130px;
      width: auto;
      justify-content: center;
      text-align: center;
      padding: 12px 16px;
      font-size: 14px;
      font-weight: 750;
      border-radius: 13px;
    }
    .ss-col-controls > .ss-admin-btn { font-size: 13px; }
    /* Disabled / preparing buttons span full width */
    .ss-col-controls > .ss-open-btn.ss-disabled,
    .ss-col-controls > .ss-open-dyn {
      flex: 1 1 100%;
      width: 100%;
      justify-content: center;
      padding: 12px 16px;
      border-radius: 13px;
    }
    /* Leave Store + helper note drop to their own full-width line */
    .ss-col-controls > .ss-leave-btn {
      flex: 1 1 100%;
      width: 100%;
      text-align: center;
      padding: 11px 16px;
      font-size: 12px;
      border-radius: 13px;
    }
    .ss-col-controls > p { flex: 1 1 100%; margin: 0; }

    /* Fundraiser strip: slim divider section, no extra side padding */
    .ss-fr-strip {
      margin-top: 0;
      padding: 12px 0 0;
      border-top: 1px solid rgba(15,23,42,0.07);
    }

    .ss-buildwrap { align-items: flex-start; max-width: 100%; width: 100%; }
    .ss-founderline { text-align: left; }
  }

  @media (prefers-reduced-motion: reduce) {
    .ss-store-card { animation: none !important; transition: none !important; }
    .ss-dot-building-anim { animation: none !important; }
    .ss-progress-bar-anim { animation: none !important; }
  }

  /* Backdrop blur is cheap on one element and expensive on a list of them: the
     compositor re-samples and re-blurs what sits behind every card on every
     scrolled frame. One hero panel is fine; eighteen store cards on a phone is
     the jump you feel under your thumb.
     Dropped on small screens only, so the desktop dashboard looks unchanged.
     The cards keep their own translucent background, so the difference is a
     slightly crisper edge rather than a missing surface. */
  @media (max-width: 850px) {
    .ss-store-card {
      backdrop-filter: none;
      -webkit-backdrop-filter: none;
    }
  }

  .ss-leave-btn {
