    text-transform: uppercase;
    transition: 0.18s ease;
  }
  .ss-leave-btn:hover { background: rgba(176,0,32,.06); }

  @media (max-width: 400px) {
    .ss-card-title { font-size: 14px; }
    .ss-card-subtitle { font-size: 11px; }
    .ss-logo-frame { width: 48px; height: 48px; }
  }

  @media (max-width: 768px) {
    .ss-user-pill { display: none !important; }
    .ss-block-hero { display: none !important; }
  }



  /* New Store Onboarding Tutorial */
  .ss-onboardingOverlay {
    position: fixed;
    inset: 0;
    z-index: 10050;
    display: none;
    align-items: center;
    justify-content: center;
    padding: 18px;
    font-family: var(--ss-font);
  }
  .ss-onboardingOverlay.is-open { display: flex; }
  .ss-onboardingBackdrop {
    position: absolute;
    inset: 0;
    background:
      radial-gradient(circle at 24% 18%, rgba(212,176,106,0.22), transparent 40%),
      rgba(15,23,42,0.58);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
  }
  .ss-onboardingCard {
    position: relative;
    width: min(1360px, calc(100vw - 56px));
    min-height: 660px;
    background:
      linear-gradient(146deg, rgba(255,252,242,0.97) 0%, rgba(248,241,222,0.95) 54%, rgba(255,255,255,0.94) 100%);
    border: 1px solid rgba(203,167,97,0.36);
    border-radius: 30px;
    box-shadow: 0 34px 120px rgba(15,23,42,0.34), inset 0 1px 0 rgba(255,255,255,0.72);
    display: grid;
    grid-template-columns: 1.22fr 0.78fr;
    overflow: hidden;
    animation: ssOnboardingIn .26s ease-out both;
  }
  @keyframes ssOnboardingIn {
    from { opacity: 0; transform: translateY(12px) scale(.985); }
    to { opacity: 1; transform: translateY(0) scale(1); }
  }
