    THE BOUNCER LOGIC
    If Shopify dumps a logged-in customer on Account/Orders, redirect them away.
    Priority:
    1. Pending storefront form -> return to saved form path.
    2. Normal login/account access -> dashboard.
  {%- endcomment -%}
  {%- assign ss_is_auth_page = false -%}
  {%- if request.path contains '/account/login' or request.path contains '/account/register' or request.path contains '/account/reset' or request.path contains '/account/activate' -%}
    {%- assign ss_is_auth_page = true -%}
  {%- endif -%}
  {%- if template.name == 'account' or template.name == 'order' or request.path contains '/account' and ss_is_auth_page == false -%}
    <script>
      (function () {
        var portal = "{{ pages['portal'].url | default: '/pages/portal' }}";
        var fallbackForm = "/pages/private-storefronts";
        var target = portal;

        try {
          var raw = localStorage.getItem('sf_pending_form_v2') || localStorage.getItem('sf_pending_form_v1');
          if (raw) {
            var data = JSON.parse(raw);
            var savedAt = Number(data && data._saved_at ? data._saved_at : 0);
            var isFresh = !savedAt || ((Date.now() - savedAt) < (1000 * 60 * 60 * 12));
            if (isFresh) {
              target = (data && data.return_path) ? data.return_path : fallbackForm;
            }
          }
        } catch (e) {}

        window.location.replace(target);
      })();
    </script>
    <style>html, body { display: none !important; }</style>
    {% layout none %}
  {%- endif -%}
{%- endunless -%}

