    {%- if customer -%}
      <script>
        (function () {
          var portalUrl = "{{ pages['portal'].url | default: '/pages/portal' }}";
          var fallbackForm = '/pages/private-storefronts';
          var path = window.location.pathname || '';

          try {
            var signinRaw = localStorage.getItem('sf_pending_signin_v1');
            if (signinRaw) {
              localStorage.removeItem('sf_pending_signin_v1');
              var signinData = JSON.parse(signinRaw);
              var signinAt = Number(signinData._saved_at || 0);
              var signinFresh = !signinAt || ((Date.now() - signinAt) < (1000 * 60 * 60 * 4));
              if (signinFresh && signinData.return_path && path !== signinData.return_path) {
                window.location.replace(signinData.return_path);
                return;
              }
            }
          } catch(e) {}

          // Resume a half-finished storefront request ONLY when landing on the
          // portal (where Shopify drops you after sign-in). Running this on
          // every page hijacked the whole site for 12 hours after any form
          // visit — blog posts, policies, everything bounced to the form.
          if (path !== portalUrl) return;

          try {
            var raw = localStorage.getItem('sf_pending_form_v2') || localStorage.getItem('sf_pending_form_v1');
            if (!raw) return;

            var data = JSON.parse(raw);
            var savedAt = Number(data && data._saved_at ? data._saved_at : 0);
            var isFresh = !savedAt || ((Date.now() - savedAt) < (1000 * 60 * 60 * 12));

            if (isFresh) {
              window.location.replace((data && data.return_path) ? data.return_path : fallbackForm);
            } else {
              localStorage.removeItem('sf_pending_form_v2');
              localStorage.removeItem('sf_pending_form_v1');
            }
          } catch(e) {}
        })();
      </script>
